-- =====================================================================
-- DEMO Academia MEGA: 3 cursos, 15 temas, 33 tests, 330 preguntas,
-- 8 usuarios de ejemplo e historial de tests. Pegar entero en el SQL
-- Editor de Neon y pulsar Run. Se aplica todo o nada (BEGIN/COMMIT).
-- Contraseña de todos los usuarios demo: MegaDemo2026
-- =====================================================================
BEGIN;

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM cursos WHERE nombre IN ('Auxiliar Administrativo del Estado', 'Policía Nacional – Escala Básica', 'Guardia Civil – Cabos y Guardias'))
     OR EXISTS (SELECT 1 FROM usuarios WHERE email IN ('alumna.demo@academiamega.net', 'profesor.demo@academiamega.net', 'sergio.demo@academiamega.net', 'elena.demo@academiamega.net', 'david.demo@academiamega.net', 'carmen.demo@academiamega.net', 'pablo.demo@academiamega.net', 'nuria.demo@academiamega.net')) THEN
    RAISE EXCEPTION 'La demo ya está cargada (existen sus cursos o usuarios). Ejecuta antes demo_borrar.sql si quieres recargarla.';
  END IF;
END $$;

