-- 5) Preguntas
INSERT INTO preguntas (enunciado, opcion_a, opcion_b, opcion_c, opcion_d, respuesta_correcta, explicacion, tema_id, test_plantilla_id)
SELECT v.enunciado, v.a, v.b, v.c, v.d, v.correcta, v.explicacion, t.id, tp.id FROM (VALUES
  (0, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 1', '¿En qué fecha se ratificó la Constitución Española en referéndum?', '27 de diciembre de 1978', '29 de diciembre de 1978', '31 de octubre de 1978', '6 de diciembre de 1978', 'D', 'Las Cortes la aprobaron el 31/10/1978, se ratificó en referéndum el 6/12/1978, el Rey la sancionó el 27/12/1978 y se publicó en el BOE el 29/12/1978.'),
  (1, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 1', '¿Cuándo entró en vigor la Constitución Española?', 'El 29 de diciembre de 1978, día de su publicación en el BOE', 'El 1 de enero de 1979', 'El 27 de diciembre de 1978', 'El 6 de diciembre de 1978', 'A', 'Según su disposición final, entra en vigor el mismo día de la publicación de su texto oficial en el BOE (29/12/1978).'),
  (2, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 1', '¿Cuántos artículos tiene la Constitución Española?', '169', '167', '196', '155', 'A', 'La CE tiene 169 artículos, 4 disposiciones adicionales, 9 transitorias, 1 derogatoria y 1 final.'),
  (3, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 1', '¿Cuántas disposiciones transitorias contiene la Constitución?', 'Diez', 'Una', 'Nueve', 'Cuatro', 'C', 'La CE contiene 9 disposiciones transitorias, 4 adicionales, 1 derogatoria y 1 final.'),
  (4, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 1', 'Según el artículo 1.1 CE, son valores superiores del ordenamiento jurídico:', 'La libertad, la justicia, la solidaridad y el pluralismo político', 'La dignidad, la justicia, la igualdad y el pluralismo político', 'La libertad, la seguridad, la igualdad y el pluralismo político', 'La libertad, la justicia, la igualdad y el pluralismo político', 'D', 'Art. 1.1 CE: España propugna como valores superiores la libertad, la justicia, la igualdad y el pluralismo político.'),
  (5, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 1', 'La forma política del Estado español es:', 'La República parlamentaria', 'La Monarquía constitucional', 'La Monarquía parlamentaria', 'La Monarquía federal', 'C', 'Art. 1.3 CE: «La forma política del Estado español es la Monarquía parlamentaria».'),
  (6, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 1', '¿En quién reside la soberanía nacional?', 'En el Gobierno de la Nación', 'En el Rey', 'En el pueblo español', 'En las Cortes Generales', 'C', 'Art. 1.2 CE: la soberanía nacional reside en el pueblo español, del que emanan los poderes del Estado.'),
  (7, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 1', '¿Qué artículo de la Constitución establece que el castellano es la lengua española oficial del Estado?', 'El artículo 3', 'El artículo 5', 'El artículo 2', 'El artículo 4', 'A', 'Art. 3.1 CE: el castellano es la lengua española oficial del Estado y todos los españoles tienen el deber de conocerla y el derecho a usarla.'),
  (8, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 1', 'Según el artículo 5 CE, la capital del Estado es:', 'La ciudad de Madrid', 'La villa de Madrid', 'La Comunidad de Madrid', 'Madrid y su área metropolitana', 'B', 'Art. 5 CE: «La capital del Estado es la villa de Madrid».'),
  (9, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 1', 'Según el artículo 4 CE, la bandera de España está formada por:', 'Dos franjas horizontales, roja y amarilla, de igual anchura', 'Tres franjas horizontales de igual anchura: roja, amarilla y roja', 'Tres franjas horizontales, roja, amarilla y roja, siendo la amarilla de doble anchura que cada una de las rojas', 'Tres franjas verticales, roja, amarilla y roja, siendo la amarilla de doble anchura', 'C', 'Art. 4.1 CE.'),
  (10, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 2', 'El derecho a la igualdad ante la ley (art. 14 CE) se encuentra en:', 'El Título Preliminar', 'El Capítulo II del Título I, antes de la Sección 1.ª', 'La Sección 1.ª del Capítulo II del Título I', 'El Capítulo III del Título I', 'B', 'El art. 14 abre el Capítulo II («Derechos y libertades») del Título I, antes de la Sección 1.ª (arts. 15 a 29).'),
  (11, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 2', '¿Qué derechos pueden protegerse mediante el recurso de amparo ante el Tribunal Constitucional?', 'Los de los artículos 14 a 38', 'Todos los derechos del Título I', 'Los de los artículos 14 a 29 y la objeción de conciencia del artículo 30.2', 'Solo los de los artículos 15 a 29', 'C', 'Art. 53.2 CE: amparo para las libertades y derechos del art. 14 y de la Sección 1.ª del Capítulo II, y para la objeción de conciencia (art. 30).'),
  (12, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 2', 'Según el texto del artículo 15 CE, queda abolida la pena de muerte, salvo:', 'Lo que puedan disponer las leyes penales militares para tiempos de guerra', 'En los supuestos que establezca una ley orgánica', 'En los delitos de terrorismo', 'En caso de estado de sitio', 'A', 'Es el texto literal del art. 15 CE. La LO 11/1995 suprimió también la pena de muerte en tiempo de guerra.'),
  (13, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 2', 'La detención preventiva no podrá durar más del tiempo estrictamente necesario y, como máximo:', '96 horas', '48 horas', '24 horas', '72 horas', 'D', 'Art. 17.2 CE: plazo máximo de 72 horas para poner al detenido en libertad o a disposición judicial.'),
  (14, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 2', '¿A qué edad son mayores de edad los españoles según la Constitución?', 'A los 14 años', 'A los 21 años', 'A los 16 años', 'A los 18 años', 'D', 'Art. 12 CE.'),
  (15, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 2', 'En las reuniones en lugares de tránsito público y manifestaciones:', 'Se dará comunicación previa a la autoridad', 'Se requiere autorización previa de la autoridad', 'Se requiere autorización judicial', 'No se exige ningún trámite', 'A', 'Art. 21.2 CE: comunicación previa; la autoridad solo puede prohibirlas por razones fundadas de alteración del orden público con peligro para personas o bienes.'),
  (16, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 2', 'El secuestro de publicaciones y otros medios de información solo podrá acordarse:', 'En virtud de resolución judicial', 'Por la autoridad gubernativa', 'Por el Ministerio Fiscal', 'Por decreto del Gobierno', 'A', 'Art. 20.5 CE.'),
  (17, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 2', 'El Defensor del Pueblo es:', 'Alto comisionado del Gobierno', 'Alto comisionado del Consejo General del Poder Judicial', 'Órgano dependiente del Ministerio de Justicia', 'Alto comisionado de las Cortes Generales', 'D', 'Art. 54 CE: designado por las Cortes Generales para la defensa de los derechos del Título I.'),
  (18, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 2', 'El procedimiento agravado de reforma constitucional (art. 168) se aplica cuando la reforma afecte a:', 'El Título VI', 'El Título VIII', 'El Título Preliminar, la Sección 1.ª del Capítulo II del Título I o el Título II', 'El Título III', 'C', 'Art. 168 CE: también se aplica a la revisión total de la Constitución.'),
  (19, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Aux. Administrativo · T1 · Test 2', '¿Quién NO puede ejercer la iniciativa de reforma constitucional?', 'El Congreso de los Diputados', 'Los ciudadanos mediante iniciativa legislativa popular', 'El Gobierno', 'El Senado', 'B', 'Art. 166 CE en relación con el art. 87.1 y 2: Gobierno, Congreso, Senado y Asambleas de las CCAA. La iniciativa popular queda excluida.'),
  (20, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Simulacro general · Aux. Administrativo', '¿Cuál de los siguientes principios NO figura en el artículo 9.3 CE?', 'La jerarquía normativa', 'La publicidad de las normas', 'El principio de oportunidad', 'La interdicción de la arbitrariedad de los poderes públicos', 'C', 'Art. 9.3 CE: legalidad, jerarquía normativa, publicidad, irretroactividad de disposiciones sancionadoras no favorables o restrictivas de derechos, seguridad jurídica, responsabilidad e interdicción de la arbitrariedad.'),
  (21, 'Auxiliar Administrativo del Estado', 'Tema 1. La Constitución Española de 1978', 'Simulacro general · Aux. Administrativo', '¿Cuáles de los siguientes son valores superiores del ordenamiento según el art. 1.1 CE? (varias correctas)', 'La libertad', 'El pluralismo político', 'La seguridad', 'La solidaridad', 'AB', 'Los cuatro valores superiores son libertad, justicia, igualdad y pluralismo político.'),
  (22, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 1', '¿Quién es el Jefe del Estado según la Constitución?', 'El Rey', 'El Presidente del Gobierno', 'El Presidente del Tribunal Constitucional', 'El Presidente del Congreso', 'A', 'Art. 56.1 CE: el Rey es el Jefe del Estado, símbolo de su unidad y permanencia.'),
  (23, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 1', 'Los actos del Rey carecerán de validez sin:', 'El refrendo', 'La aprobación del Congreso', 'La firma del Presidente del Tribunal Supremo', 'El dictamen del Consejo de Estado', 'A', 'Art. 56.3 CE: la persona del Rey es inviolable y no está sujeta a responsabilidad; sus actos estarán siempre refrendados.'),
  (24, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 1', '¿Quién refrenda la propuesta y el nombramiento del Presidente del Gobierno?', 'El Ministro de Justicia', 'El Presidente del Congreso', 'El Presidente del Senado', 'El Presidente del Gobierno en funciones', 'B', 'Art. 64.1 CE.'),
  (25, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 1', 'El heredero de la Corona tendrá la dignidad de:', 'Duque de Asturias', 'Príncipe de Asturias', 'Príncipe de Viana', 'Príncipe de Gerona', 'B', 'Art. 57.2 CE.'),
  (26, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 1', 'Cuando el Rey sea menor de edad, ejercerá la Regencia:', 'Una Regencia de tres personas nombrada por las Cortes', 'El Presidente del Gobierno', 'El Presidente del Congreso', 'El padre o la madre del Rey y, en su defecto, el pariente mayor de edad más próximo a suceder', 'D', 'Art. 59.1 CE. Solo si no hubiera ninguna persona a quien corresponda, las Cortes nombran una Regencia de una, tres o cinco personas (art. 59.3).'),
  (27, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 1', 'Las Cortes Generales están formadas por:', 'El Congreso y el Consejo de Estado', 'El Congreso de los Diputados y el Senado', 'El Congreso, el Senado y el Gobierno', 'El Congreso, el Senado y el Defensor del Pueblo', 'B', 'Art. 66.1 CE.'),
  (28, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 1', 'El Congreso se compone de:', 'Un mínimo de 300 y un máximo de 400 Diputados', 'Un mínimo de 250 y un máximo de 350 Diputados', 'Un mínimo de 300 y un máximo de 450 Diputados', '350 Diputados fijados por la Constitución', 'A', 'Art. 68.1 CE. La LOREG fija actualmente 350.'),
  (29, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 1', 'El mandato de los Diputados y Senadores es de:', 'Cuatro años', 'Cinco años', 'Tres años', 'Seis años', 'A', 'Arts. 68.4 y 69.6 CE.'),
  (30, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 1', 'En las elecciones al Congreso, las poblaciones de Ceuta y Melilla eligen:', 'Dos Diputados cada una', 'Un Diputado cada una', 'Un Diputado entre ambas', 'Ninguno; se integran en Cádiz y Málaga', 'B', 'Art. 68.2 CE.'),
  (31, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 1', 'Según la Constitución, el Senado es:', 'La Cámara de representación territorial', 'La Cámara de segunda lectura sin funciones propias', 'La Cámara de representación de los ciudadanos', 'La Cámara de control del Gobierno', 'A', 'Art. 69.1 CE.'),
  (32, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 2', '¿Cuántos Senadores elige cada provincia peninsular?', 'Cinco', 'Dos', 'Tres', 'Cuatro', 'D', 'Art. 69.2 CE.'),
  (33, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 2', '¿Cuántos Senadores eligen cada una de las islas mayores (Gran Canaria, Mallorca y Tenerife)?', 'Dos', 'Uno', 'Tres', 'Cuatro', 'C', 'Art. 69.3 CE. El resto de islas o agrupaciones eligen uno.'),
  (34, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 2', 'La aprobación de las leyes orgánicas exige:', 'Tres quintos de cada Cámara', 'Mayoría simple de ambas Cámaras', 'Mayoría absoluta del Congreso en una votación final sobre el conjunto del proyecto', 'Mayoría absoluta de ambas Cámaras', 'C', 'Art. 81.2 CE.'),
  (35, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 2', '¿De qué plazo dispone el Senado, con carácter general, para oponer su veto o introducir enmiendas a un proyecto de ley?', 'Veinte días naturales', 'Dos meses', 'Un mes', 'Tres meses', 'B', 'Art. 90.2 CE. Se reduce a veinte días naturales en los proyectos declarados urgentes.'),
  (36, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 2', 'El veto del Senado a un proyecto de ley debe aprobarse por:', 'Mayoría absoluta', 'Dos tercios', 'Tres quintos', 'Mayoría simple', 'A', 'Art. 90.2 CE. El Congreso puede levantarlo por mayoría absoluta o, pasados dos meses, por mayoría simple.'),
  (37, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 2', '¿Cuántas firmas acreditadas exige la iniciativa legislativa popular?', 'No menos de 750.000', 'No menos de 500.000', 'No menos de 1.000.000', 'No menos de 300.000', 'B', 'Art. 87.3 CE.'),
  (38, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 2', '¿Cuál de estas materias SÍ puede ser objeto de iniciativa legislativa popular?', 'La prerrogativa de gracia', 'Una materia tributaria', 'Una materia propia de ley orgánica', 'Una ley ordinaria de protección del medio ambiente', 'D', 'Art. 87.3 CE: se excluyen materias de ley orgánica, tributarias, de carácter internacional y la prerrogativa de gracia.'),
  (39, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 2', 'El Rey sancionará las leyes aprobadas por las Cortes Generales en el plazo de:', 'Diez días', 'Veinte días', 'Treinta días', 'Quince días', 'D', 'Art. 91 CE.'),
  (40, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 2', 'Los decretos-leyes deben someterse a debate y votación de totalidad:', 'En el Congreso, en los 15 días siguientes', 'En ambas Cámaras, en los 60 días siguientes', 'En el Congreso, en los 30 días siguientes a su promulgación', 'En el Senado, en los 15 días siguientes', 'C', 'Art. 86.2 CE.'),
  (41, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Aux. Administrativo · T2 · Test 2', 'Durante su mandato, los Diputados y Senadores solo podrán ser detenidos:', 'En caso de flagrante delito', 'Con autorización del Tribunal Supremo', 'En ningún caso', 'Con autorización del Rey', 'A', 'Art. 71.2 CE. Para inculparlos o procesarlos se requiere autorización de la Cámara respectiva.'),
  (42, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Simulacro general · Aux. Administrativo', '¿Qué órgano es competente en las causas contra Diputados y Senadores?', 'La Audiencia Nacional', 'El Tribunal Superior de Justicia de su Comunidad', 'La Sala de lo Penal del Tribunal Supremo', 'El Tribunal Constitucional', 'C', 'Art. 71.3 CE.'),
  (43, 'Auxiliar Administrativo del Estado', 'Tema 2. La Corona y las Cortes Generales', 'Simulacro general · Aux. Administrativo', 'Además de los senadores provinciales, las Comunidades Autónomas designan:', 'Dos Senadores cada una', 'Un Senador y otro más por cada millón de habitantes de su territorio', 'Un Senador por cada provincia que la integre', 'Un Senador por cada 500.000 habitantes', 'B', 'Art. 69.5 CE.'),
  (44, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 1', 'Según el artículo 98 CE, el Gobierno se compone de:', 'El Presidente y los Ministros exclusivamente', 'El Presidente, los Vicepresidentes en su caso, los Ministros y los demás miembros que establezca la ley', 'El Presidente, los Ministros y los Delegados del Gobierno', 'El Presidente, los Ministros y los Secretarios de Estado', 'B', 'Art. 98.1 CE.'),
  (45, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 1', '¿Quién ejerce la potestad reglamentaria de acuerdo con la Constitución y las leyes?', 'El Consejo General del Poder Judicial', 'El Rey', 'El Gobierno', 'Las Cortes Generales', 'C', 'Art. 97 CE: el Gobierno ejerce la función ejecutiva y la potestad reglamentaria.'),
  (46, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 1', '¿Quién propone el candidato a la Presidencia del Gobierno?', 'El partido más votado', 'La Mesa del Congreso', 'El Rey, previa consulta con los representantes de los grupos políticos con representación parlamentaria', 'El Presidente del Congreso', 'C', 'Art. 99.1 CE. La propuesta se formula a través del Presidente del Congreso.'),
  (47, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 1', 'Si el candidato no obtiene la mayoría absoluta en la primera votación de investidura, se somete a nueva votación:', 'Una semana después, por mayoría simple', '48 horas después, bastando la mayoría simple', '24 horas después, por mayoría absoluta', '72 horas después, por mayoría de tres quintos', 'B', 'Art. 99.3 CE.'),
  (48, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 1', 'Si transcurridos dos meses desde la primera votación ningún candidato obtiene la confianza del Congreso:', 'Se celebra una votación en el Senado', 'El Rey disuelve ambas Cámaras y convoca nuevas elecciones', 'Gobierna el candidato con más votos', 'El Presidente del Congreso es investido automáticamente', 'B', 'Art. 99.5 CE. El Real Decreto se refrenda por el Presidente del Congreso.'),
  (49, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 1', 'La moción de censura debe ser propuesta al menos por:', 'La mayoría absoluta del Congreso', 'Cincuenta Diputados o Senadores', 'La quinta parte de los Diputados', 'La décima parte de los Diputados e incluir un candidato a la Presidencia', 'D', 'Art. 113.2 CE. Para aprobarse requiere la mayoría absoluta del Congreso.'),
  (50, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 1', 'La moción de censura no podrá ser votada hasta que transcurran:', '48 horas desde su presentación', 'Diez días desde su presentación', 'Dos días desde su presentación', 'Cinco días desde su presentación', 'D', 'Art. 113.3 CE. En los dos primeros días podrán presentarse mociones alternativas.'),
  (51, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 1', 'En la cuestión de confianza, esta se entiende otorgada cuando vote a favor:', 'Tres quintos del Congreso', 'La mayoría absoluta de los Diputados', 'La mayoría simple de ambas Cámaras', 'La mayoría simple de los Diputados', 'D', 'Art. 112 CE.'),
  (52, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 1', '¿Cuál de las siguientes NO es causa de cese del Gobierno según el art. 101 CE?', 'La dimisión de un Vicepresidente', 'La celebración de elecciones generales', 'La pérdida de la confianza parlamentaria', 'El fallecimiento de su Presidente', 'A', 'Art. 101.1 CE: elecciones generales, pérdida de confianza parlamentaria, dimisión o fallecimiento del Presidente.'),
  (53, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 1', 'La acusación contra miembros del Gobierno por traición o delito contra la seguridad del Estado solo puede plantearse a iniciativa de:', 'El Fiscal General del Estado', 'La cuarta parte de los miembros del Congreso, con la aprobación de su mayoría absoluta', 'La décima parte de los Diputados', 'La mayoría absoluta del Senado', 'B', 'Art. 102.2 CE.'),
  (54, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 2', '¿Cuál de los siguientes principios NO figura en el artículo 103.1 CE?', 'Jerarquía', 'Centralización', 'Eficacia', 'Desconcentración', 'B', 'Art. 103.1 CE: eficacia, jerarquía, descentralización, desconcentración y coordinación, con sometimiento pleno a la ley y al Derecho.'),
  (55, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 2', '¿Qué ley regula el Régimen Jurídico del Sector Público?', 'La Ley 50/1997, de 27 de noviembre', 'La Ley 40/2015, de 1 de octubre', 'La Ley 30/1992, de 26 de noviembre', 'La Ley 39/2015, de 1 de octubre', 'B', 'La Ley 39/2015 regula el procedimiento administrativo común; la Ley 50/1997 es la Ley del Gobierno; la Ley 30/1992 está derogada.'),
  (56, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 2', '¿Qué norma es la Ley del Gobierno?', 'La Ley 50/1997, de 27 de noviembre', 'La Ley 40/2015, de 1 de octubre', 'La Ley 6/1997, de 14 de abril', 'La Ley 29/1998, de 13 de julio', 'A', 'La Ley 6/1997 (LOFAGE) está derogada; la Ley 29/1998 regula la jurisdicción contencioso-administrativa.'),
  (57, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 2', 'En la Administración General del Estado son órganos superiores:', 'Los Subsecretarios y los Directores generales', 'Los Ministros y los Secretarios de Estado', 'Los Ministros y los Subsecretarios', 'Los Secretarios de Estado y los Secretarios generales', 'B', 'Art. 55 de la Ley 40/2015.'),
  (58, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 2', '¿Cuál de los siguientes es un órgano directivo de la Administración General del Estado?', 'El Presidente del Gobierno', 'El Ministro', 'El Secretario de Estado', 'El Director general', 'D', 'Art. 55 de la Ley 40/2015: Subsecretarios, Secretarios generales, Secretarios generales técnicos, Directores generales y Subdirectores generales.'),
  (59, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 2', '¿Qué órgano dirige la Administración del Estado en el territorio de una Comunidad Autónoma?', 'El Presidente de la Comunidad Autónoma', 'El Subdelegado del Gobierno', 'El Consejero de Presidencia', 'El Delegado del Gobierno', 'D', 'Art. 154 CE y Ley 40/2015.'),
  (60, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 2', '¿Quién nombra a los Subdelegados del Gobierno en las provincias?', 'El Consejo de Ministros', 'El Ministro de Política Territorial', 'El Presidente del Gobierno', 'El Delegado del Gobierno, por libre designación entre funcionarios de carrera', 'D', 'Ley 40/2015.'),
  (61, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 2', '¿Cuál es el supremo órgano consultivo del Gobierno?', 'El Consejo Económico y Social', 'El Consejo de Estado', 'El Tribunal de Cuentas', 'El Consejo General del Poder Judicial', 'B', 'Art. 107 CE.'),
  (62, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 2', 'Según el artículo 137 CE, el Estado se organiza territorialmente en:', 'Municipios, comarcas y Comunidades Autónomas', 'Municipios, provincias y Comunidades Autónomas', 'Provincias y Comunidades Autónomas', 'Municipios, provincias, islas y regiones', 'B', 'Art. 137 CE: todas estas entidades gozan de autonomía para la gestión de sus respectivos intereses.'),
  (63, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Aux. Administrativo · T3 · Test 2', 'La disolución anticipada de las Cámaras NO podrá proponerse:', 'Sin el acuerdo del Senado', 'Cuando esté en trámite una moción de censura', 'Durante el periodo de sesiones', 'Durante el primer año de legislatura', 'B', 'Art. 115.2 CE. Además, no cabe nueva disolución antes de un año desde la anterior (art. 115.3).'),
  (64, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Simulacro general · Aux. Administrativo', 'Los Ministros son nombrados y separados por:', 'El Rey, a propuesta del Congreso', 'El Congreso de los Diputados', 'El Rey, a propuesta del Presidente del Gobierno', 'El Presidente del Gobierno directamente', 'C', 'Art. 100 CE.'),
  (65, 'Auxiliar Administrativo del Estado', 'Tema 3. El Gobierno y la Administración', 'Simulacro general · Aux. Administrativo', '¿Quién nombra al Delegado del Gobierno en una Comunidad Autónoma?', 'El Consejo de Ministros, mediante Real Decreto, a propuesta del Presidente del Gobierno', 'El Ministro del Interior', 'El Presidente de la Comunidad Autónoma', 'El Rey, a propuesta del Congreso', 'A', 'Ley 40/2015.'),
  (66, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 1', '¿Qué ley regula el Procedimiento Administrativo Común de las Administraciones Públicas?', 'La Ley 30/1992, de 26 de noviembre', 'La Ley 40/2015, de 1 de octubre', 'La Ley 39/2015, de 1 de octubre', 'La Ley 29/1998, de 13 de julio', 'C', 'La Ley 39/2015 sustituyó en esta materia a la Ley 30/1992.'),
  (67, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 1', 'Cuando la norma reguladora del procedimiento no fije plazo máximo para resolver, este será de:', 'Dos meses', 'Seis meses', 'Tres meses', 'Un mes', 'C', 'Art. 21.3 de la Ley 39/2015.'),
  (68, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 1', 'El plazo máximo para resolver fijado por la norma reguladora no podrá exceder, con carácter general, de:', 'Seis meses, salvo que una ley o el Derecho de la UE prevean uno mayor', 'Un año', 'Nueve meses', 'Tres meses', 'A', 'Art. 21.2 de la Ley 39/2015.'),
  (69, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 1', 'Salvo disposición en contrario, cuando los plazos se señalen por días se entiende que son:', 'Hábiles, excluyéndose sábados, domingos y festivos', 'Hábiles, excluyéndose solo domingos y festivos', 'Naturales', 'Hábiles, excluyéndose sábados y domingos pero no festivos', 'A', 'Art. 30.2 de la Ley 39/2015.'),
  (70, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 1', 'En un plazo fijado en meses, si en el mes de vencimiento no hubiera día equivalente al inicial:', 'Se añaden tres días naturales', 'El plazo expira el primer día del mes siguiente', 'El plazo expira el último día del mes', 'Se prorroga automáticamente un mes', 'C', 'Art. 30.5 de la Ley 39/2015.'),
  (71, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 1', 'En los procedimientos iniciados a solicitud del interesado, la regla general del silencio administrativo es:', 'Sin efectos', 'Estimatoria', 'Desestimatoria', 'Estimatoria solo si lo autoriza el superior jerárquico', 'B', 'Art. 24.1 de la Ley 39/2015, con las excepciones que la propia ley enumera.'),
  (72, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 1', '¿En cuál de estos procedimientos iniciados a solicitud el silencio tiene efecto desestimatorio?', 'En todos los iniciados a solicitud del interesado', 'Solo en los que afecten a personas físicas', 'En los de responsabilidad patrimonial de las Administraciones Públicas', 'En ninguno: el silencio siempre es estimatorio', 'C', 'Art. 24.1 de la Ley 39/2015.'),
  (73, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 1', 'Los procedimientos administrativos podrán iniciarse:', 'De oficio, a solicitud del interesado o por orden judicial exclusivamente', 'Solo a solicitud del interesado', 'De oficio o a solicitud del interesado', 'Solo de oficio', 'C', 'Art. 54 de la Ley 39/2015.'),
  (74, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 1', 'Si la solicitud de iniciación no reúne los requisitos, se requerirá al interesado para que subsane en un plazo de:', 'Diez días', 'Quince días', 'Cinco días', 'Un mes', 'A', 'Art. 68.1 de la Ley 39/2015, con indicación de que, si no lo hiciera, se le tendrá por desistido.'),
  (75, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 1', 'El plazo para interponer el recurso de alzada contra un acto expreso es de:', 'Dos meses', 'Un mes', 'Quince días', 'Tres meses', 'B', 'Art. 122.1 de la Ley 39/2015.'),
  (76, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 2', 'El recurso de reposición tiene carácter:', 'Extraordinario', 'Previo y necesario al recurso de alzada', 'Obligatorio', 'Potestativo', 'D', 'Art. 123 de la Ley 39/2015: contra actos que ponen fin a la vía administrativa.'),
  (77, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 2', 'El plazo máximo para dictar y notificar la resolución del recurso de reposición es de:', 'Tres meses', 'Un mes', 'Dos meses', 'Quince días', 'B', 'Art. 124.2 de la Ley 39/2015. En el recurso de alzada es de tres meses (art. 122.2).'),
  (78, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 2', 'El recurso extraordinario de revisión procede contra:', 'Disposiciones de carácter general', 'Cualquier acto de trámite', 'Actos que no ponen fin a la vía administrativa', 'Actos firmes en vía administrativa, en los supuestos tasados por la ley', 'D', 'Art. 125 de la Ley 39/2015.'),
  (79, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 2', '¿Cuál de los siguientes actos es nulo de pleno derecho?', 'El dictado prescindiendo total y absolutamente del procedimiento legalmente establecido', 'El que tenga un defecto de forma subsanable', 'El dictado fuera del plazo establecido', 'El que incurra en cualquier infracción del ordenamiento jurídico', 'A', 'Art. 47.1.e de la Ley 39/2015. Las demás opciones son, en su caso, supuestos de anulabilidad (art. 48).'),
  (80, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 2', '¿Quién está obligado a relacionarse electrónicamente con las Administraciones Públicas?', 'Todas las personas físicas', 'Las personas jurídicas', 'Nadie: siempre es voluntario', 'Los mayores de 65 años', 'B', 'Art. 14.2 de la Ley 39/2015.'),
  (81, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 2', 'Toda notificación deberá cursarse dentro del plazo de:', 'Cinco días', 'Un mes', 'Quince días', 'Diez días a partir de la fecha en que el acto haya sido dictado', 'D', 'Art. 40.2 de la Ley 39/2015.'),
  (82, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 2', 'Una notificación electrónica se entiende rechazada cuando, sin acceder a su contenido, hayan transcurrido desde su puesta a disposición:', 'Diez días hábiles', 'Quince días naturales', 'Diez días naturales', 'Cinco días naturales', 'C', 'Art. 43.2 de la Ley 39/2015.'),
  (83, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 2', 'Es motivo de abstención tener parentesco de consanguinidad con el interesado dentro del:', 'Tercer grado', 'Quinto grado', 'Segundo grado', 'Cuarto grado', 'D', 'Art. 23.2.b de la Ley 40/2015: consanguinidad dentro del cuarto grado o afinidad dentro del segundo.'),
  (84, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 2', '¿Cuál de las siguientes NO es una fase del procedimiento administrativo?', 'La finalización', 'La iniciación', 'La instrucción', 'La deliberación', 'D', 'La Ley 39/2015 regula la iniciación, ordenación, instrucción y finalización (y la ejecución).'),
  (85, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Aux. Administrativo · T4 · Test 2', 'En el trámite de audiencia, los interesados dispondrán de un plazo:', 'No inferior a cinco días ni superior a diez', 'No inferior a diez días ni superior a quince', 'No inferior a quince días ni superior a veinte', 'De un mes', 'B', 'Art. 82.2 de la Ley 39/2015.'),
  (86, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Simulacro general · Aux. Administrativo', 'En el trámite de información pública, el plazo para formular alegaciones no podrá ser inferior a:', 'Treinta días', 'Veinte días', 'Diez días', 'Quince días', 'B', 'Art. 83.2 de la Ley 39/2015.'),
  (87, 'Auxiliar Administrativo del Estado', 'Tema 4. El procedimiento administrativo común', 'Simulacro general · Aux. Administrativo', '¿Cuál de las siguientes NO es una forma de terminación del procedimiento?', 'La declaración de caducidad', 'La subsanación de la solicitud', 'La resolución', 'El desistimiento', 'B', 'Art. 84.1 de la Ley 39/2015: resolución, desistimiento, renuncia, caducidad e imposibilidad material de continuarlo por causas sobrevenidas.'),
  (88, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 1', '¿Qué norma aprueba el texto refundido del Estatuto Básico del Empleado Público?', 'La Ley 30/1984, de 2 de agosto', 'El Real Decreto Legislativo 2/2015, de 23 de octubre', 'La Ley 7/2007, de 12 de abril', 'El Real Decreto Legislativo 5/2015, de 30 de octubre', 'D', 'El RDL 2/2015 es el Estatuto de los Trabajadores; la Ley 7/2007 fue el EBEP original, hoy refundido.'),
  (89, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 1', '¿Cuál de los siguientes NO es una clase de empleado público según el TREBEP?', 'El funcionario interino', 'El personal laboral', 'El personal autónomo', 'El personal eventual', 'C', 'Art. 8 TREBEP: funcionarios de carrera, funcionarios interinos, personal laboral y personal eventual.'),
  (90, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 1', 'El Cuerpo General Auxiliar de la Administración del Estado pertenece al subgrupo:', 'C1', 'A2', 'B', 'C2', 'D', 'Art. 76 TREBEP: grupos A (A1, A2), B y C (C1, C2).'),
  (91, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 1', 'Para el acceso al subgrupo C2 se exige el título de:', 'Bachiller o Técnico', 'Técnico Superior', 'Graduado en Educación Secundaria Obligatoria', 'Grado universitario', 'C', 'Art. 76 TREBEP.'),
  (92, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 1', 'La edad mínima para acceder al empleo público es de:', 'Dieciséis años', 'Veintiún años', 'Dieciocho años', 'Diecisiete años', 'A', 'Art. 56.1.c TREBEP: tener cumplidos dieciséis años y no exceder la edad máxima de jubilación forzosa.'),
  (93, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 1', 'El personal eventual realiza funciones:', 'Exclusivamente de carácter técnico', 'Propias de los funcionarios de carrera', 'De carácter estructural y permanente', 'Expresamente calificadas como de confianza o asesoramiento especial', 'D', 'Art. 12 TREBEP.'),
  (94, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 1', 'Cuando un funcionario interino ocupa una plaza vacante, si esta no se cubre, su nombramiento finaliza transcurridos:', 'Tres años', 'Cinco años', 'Cuatro años', 'Dos años', 'A', 'Art. 10.4 TREBEP, tras la reforma de la Ley 20/2021.'),
  (95, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 1', '¿Cuál de las siguientes NO es una situación administrativa de los funcionarios?', 'El servicio activo', 'La comisión de servicios', 'Los servicios especiales', 'La excedencia', 'B', 'Art. 85 TREBEP. La comisión de servicios es una forma de provisión de puestos.'),
  (96, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 1', 'La excedencia por cuidado de cada hijo tiene una duración no superior a:', 'Tres años', 'Dos años', 'Cinco años', 'Un año', 'A', 'Art. 89.4 TREBEP.'),
  (97, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 1', 'Para solicitar la excedencia voluntaria por interés particular se exige haber prestado servicios efectivos en las AAPP durante al menos:', 'Cinco años inmediatamente anteriores', 'Dos años', 'Tres años', 'Diez años', 'A', 'Art. 89.2 TREBEP.'),
  (98, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 2', 'La suspensión de funciones firme no podrá exceder de:', 'Diez años', 'Tres años', 'Cuatro años', 'Seis años', 'D', 'Art. 90.1 TREBEP.'),
  (99, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 2', 'Según el TREBEP, las faltas disciplinarias se clasifican en:', 'Gravísimas, graves y leves', 'Muy graves y graves', 'Graves y leves', 'Muy graves, graves y leves', 'D', 'Art. 95.1 TREBEP.'),
  (100, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 2', 'Las faltas leves prescriben a los:', 'Tres meses', 'Seis meses', 'Dos años', 'Un año', 'B', 'Art. 97 TREBEP: muy graves a los 3 años, graves a los 2 años y leves a los 6 meses.'),
  (101, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 2', 'La sanción de separación del servicio de los funcionarios solo puede imponerse por:', 'Faltas muy graves', 'Cualquier tipo de falta', 'Faltas graves', 'Faltas leves reiteradas', 'A', 'Art. 96.1.a TREBEP.'),
  (102, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 2', 'Los funcionarios tendrán derecho a disfrutar como mínimo de unas vacaciones retribuidas de:', 'Veinte días hábiles', 'Treinta días naturales', 'Veinticinco días hábiles', 'Veintidós días hábiles por año completo de servicio', 'D', 'Art. 50 TREBEP.'),
  (103, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 2', 'El permiso por razón de matrimonio es de:', 'Siete días', 'Quince días', 'Veinte días', 'Diez días', 'B', 'Art. 48.l TREBEP.'),
  (104, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 2', '¿Cuántos días de permiso por asuntos particulares reconoce el TREBEP?', 'Cuatro días al año', 'Ocho días al año', 'Tres días al año', 'Seis días al año', 'D', 'Art. 48.k TREBEP.'),
  (105, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 2', 'Son retribuciones básicas de los funcionarios:', 'El complemento de destino', 'El complemento específico', 'El complemento de productividad', 'El sueldo y los trienios', 'D', 'Art. 23 TREBEP (los componentes de sueldo y trienios de las pagas extraordinarias también son básicos).'),
  (106, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 2', 'Los trienios consisten en:', 'Una cantidad igual para cada subgrupo por cada tres años de servicio', 'Una paga extraordinaria cada tres años', 'Un incremento del 3 % anual', 'Un complemento vinculado al puesto de trabajo', 'A', 'Art. 23.b TREBEP.'),
  (107, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Aux. Administrativo · T5 · Test 2', '¿Cuántas pagas extraordinarias perciben los funcionarios al año?', 'Tres', 'Cuatro', 'Una', 'Dos', 'D', 'Art. 22.4 TREBEP.'),
  (108, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Simulacro general · Aux. Administrativo', '¿Cuál de las siguientes NO es causa de pérdida de la condición de funcionario de carrera?', 'La excedencia voluntaria', 'La sanción disciplinaria firme de separación del servicio', 'La renuncia', 'La jubilación total', 'A', 'Art. 63 TREBEP: renuncia, pérdida de la nacionalidad, jubilación total, separación del servicio firme e inhabilitación absoluta o especial firme.'),
  (109, 'Auxiliar Administrativo del Estado', 'Tema 5. El personal al servicio de las Administraciones Públicas', 'Simulacro general · Aux. Administrativo', 'La jubilación forzosa de los funcionarios se declara de oficio al cumplir:', 'Setenta años', 'Sesenta y siete años', 'Sesenta y cinco años', 'Sesenta años', 'C', 'Art. 67.3 TREBEP, sin perjuicio de la posibilidad de prolongar la permanencia en el servicio hasta los setenta años.'),
  (110, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 1', 'Según el artículo 1.1 del Código Civil, las fuentes del ordenamiento jurídico español son:', 'La ley, la costumbre y la doctrina científica', 'La Constitución, la ley y la jurisprudencia', 'La ley, la costumbre y los principios generales del derecho', 'La ley, la jurisprudencia y la costumbre', 'C', 'Art. 1.1 CC.'),
  (111, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 1', 'Según el Código Civil, la jurisprudencia:', 'Carece de cualquier valor jurídico', 'Es fuente directa del Derecho', 'Tiene el mismo rango que la ley', 'Complementará el ordenamiento jurídico', 'D', 'Art. 1.6 CC: complementa el ordenamiento con la doctrina reiterada del Tribunal Supremo.'),
  (112, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 1', 'La costumbre solo regirá:', 'Con preferencia a la ley', 'Solo en materia penal', 'En defecto de ley aplicable, siempre que no sea contraria a la moral o al orden público y resulte probada', 'Únicamente si la reconoce una sentencia del Tribunal Supremo', 'C', 'Art. 1.3 CC.'),
  (113, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 1', 'Si en ellas no se dispone otra cosa, las leyes entran en vigor:', 'A los quince días de su aprobación', 'Al día siguiente de su publicación', 'Al mes de su publicación', 'A los veinte días de su completa publicación en el BOE', 'D', 'Art. 2.1 CC.'),
  (114, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 1', '¿Cuál de las siguientes normas tiene rango de ley?', 'El Real Decreto-ley', 'La Orden Ministerial', 'El Real Decreto', 'La Instrucción de servicio', 'A', 'Los decretos-leyes (art. 86 CE) y los decretos legislativos (art. 82 CE) tienen rango de ley.'),
  (115, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 1', 'La delegación legislativa para la formación de textos articulados debe otorgarse mediante:', 'Una ley ordinaria', 'Una ley orgánica', 'Una ley de bases', 'Un decreto-ley', 'C', 'Art. 82.2 CE. Para refundir varios textos legales en uno solo basta una ley ordinaria.'),
  (116, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 1', 'Toda persona detenida debe ser informada de forma inmediata, y de modo que le sea comprensible:', 'De la pena que puede corresponderle', 'De sus derechos y de las razones de su detención, no pudiendo ser obligada a declarar', 'De sus derechos, únicamente cuando llegue a dependencias policiales', 'Solo de las razones de su detención', 'B', 'Art. 17.3 CE.'),
  (117, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 1', 'El procedimiento de «habeas corpus» tiene por objeto:', 'Producir la inmediata puesta a disposición judicial de toda persona detenida ilegalmente', 'Reclamar una indemnización por error judicial', 'Recurrir una sentencia penal firme', 'Solicitar la libertad provisional bajo fianza', 'A', 'Art. 17.4 CE, desarrollado por la LO 6/1984.'),
  (118, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 1', '¿Cuál de las siguientes NO permite la entrada o registro en un domicilio?', 'El consentimiento del titular', 'Un caso de flagrante delito', 'Una resolución judicial', 'Una orden del Ministerio del Interior', 'D', 'Art. 18.2 CE.'),
  (119, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 1', 'Se garantiza el secreto de las comunicaciones, salvo:', 'Autorización del Delegado del Gobierno', 'Resolución judicial', 'Decisión del responsable policial de la investigación', 'Orden del Ministerio Fiscal', 'B', 'Art. 18.3 CE.'),
  (120, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 2', '¿Cuál de los siguientes derechos NO se reconoce en el artículo 24.2 CE?', 'Un proceso público sin dilaciones indebidas', 'Ser juzgado por un jurado en todo caso', 'No declarar contra sí mismo', 'La presunción de inocencia', 'B', 'El jurado se recoge en el art. 125 CE para los procesos que determine la ley, no como derecho en todo caso.'),
  (121, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 2', 'El principio de legalidad penal establece que nadie puede ser condenado por acciones u omisiones que:', 'En el momento de producirse no constituyan delito, falta o infracción administrativa según la legislación vigente', 'No hayan sido denunciadas en plazo', 'No consten en un atestado policial', 'No hayan sido reconocidas por el acusado', 'A', 'Art. 25.1 CE.'),
  (122, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 2', 'Las penas privativas de libertad estarán orientadas hacia:', 'La reeducación y reinserción social', 'La reparación económica a la víctima', 'La prevención general exclusivamente', 'El castigo ejemplar', 'A', 'Art. 25.2 CE: además, no podrán consistir en trabajos forzados.'),
  (123, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 2', 'Según el artículo 16 CE, nadie podrá ser obligado a declarar sobre:', 'Su nacionalidad', 'Su domicilio', 'Su ideología, religión o creencias', 'Su situación económica', 'C', 'Art. 16.2 CE.'),
  (124, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 2', 'El derecho de los españoles a entrar y salir libremente de España:', 'No podrá ser limitado por motivos políticos o ideológicos', 'Puede limitarse por decreto del Gobierno en cualquier caso', 'Requiere autorización administrativa previa', 'Solo se reconoce a los mayores de edad', 'A', 'Art. 19 CE.'),
  (125, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 2', '¿Cuál de los siguientes derechos NO puede suspenderse en los estados de excepción o de sitio?', 'El derecho a la vida', 'La inviolabilidad del domicilio', 'La libertad de circulación', 'El derecho de reunión', 'A', 'Art. 55.1 CE: enumera los derechos suspendibles (arts. 17, 18.2 y 3, 19, 20.1.a y d y 20.5, 21, 28.2 y 37.2).'),
  (126, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 2', 'El estado de alarma lo declara el Gobierno por un plazo máximo de:', 'Sesenta días, prorrogables', 'Diez días, previa autorización del Senado', 'Quince días, dando cuenta al Congreso', 'Treinta días, previa autorización del Congreso', 'C', 'Art. 116.2 CE. Su prórroga requiere autorización expresa del Congreso.'),
  (127, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 2', 'El estado de excepción no podrá exceder de:', 'Sesenta días', 'Treinta días, prorrogables por otro plazo igual', 'Noventa días', 'Quince días, improrrogables', 'B', 'Art. 116.3 CE. Se declara previa autorización del Congreso.'),
  (128, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 2', 'El estado de sitio lo declara:', 'El Congreso, por mayoría absoluta, a propuesta exclusiva del Gobierno', 'El Gobierno, dando cuenta al Congreso', 'El Senado, por mayoría absoluta', 'El Rey, a propuesta del Ministro de Defensa', 'A', 'Art. 116.4 CE.'),
  (129, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Policía Nacional · T1 · Test 2', 'Los miembros de Cuerpos sometidos a disciplina militar podrán ejercer el derecho de petición:', 'Colectivamente, a través de sus asociaciones', 'Solo a través de sus mandos', 'En ningún caso', 'Solo individualmente y con arreglo a su legislación específica', 'D', 'Art. 29.2 CE.'),
  (130, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Simulacro general · Policía Nacional', 'Según el artículo 104.1 CE, las Fuerzas y Cuerpos de Seguridad tienen como misión:', 'Auxiliar exclusivamente a la Administración de Justicia', 'Defender el ordenamiento constitucional frente a agresiones exteriores', 'Garantizar la soberanía e independencia de España', 'Proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana', 'D', 'Art. 104.1 CE: actúan bajo la dependencia del Gobierno.'),
  (131, 'Policía Nacional – Escala Básica', 'Tema 1. El Derecho y la Constitución: derechos fundamentales', 'Simulacro general · Policía Nacional', 'La ignorancia de las leyes:', 'Exime de responsabilidad si se prueba', 'Solo excusa en materia administrativa', 'No excusa de su cumplimiento', 'Atenúa siempre la responsabilidad', 'C', 'Art. 6.1 CC.'),
  (132, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 1', 'La Declaración Universal de Derechos Humanos fue adoptada por la Asamblea General de la ONU:', 'El 26 de junio de 1945, en San Francisco', 'El 16 de diciembre de 1966, en Nueva York', 'El 4 de noviembre de 1950, en Roma', 'El 10 de diciembre de 1948, en París', 'D', 'Por eso el 10 de diciembre es el Día de los Derechos Humanos.'),
  (133, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 1', '¿Cuántos artículos tiene la Declaración Universal de Derechos Humanos?', '25', '30', '31', '40', 'B', 'La DUDH consta de un preámbulo y 30 artículos.'),
  (134, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 1', 'El artículo 1 de la DUDH establece que todos los seres humanos:', 'Son iguales ante la ley', 'Nacen libres e iguales en dignidad y derechos', 'Tienen derecho a la vida, la libertad y la seguridad', 'Tienen derecho a una nacionalidad', 'B', 'Art. 1 DUDH: dotados de razón y conciencia, deben comportarse fraternalmente los unos con los otros.'),
  (135, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 1', 'El derecho a la vida, a la libertad y a la seguridad de la persona se recoge en el artículo:', '1 de la DUDH', '5 de la DUDH', '9 de la DUDH', '3 de la DUDH', 'D', 'Art. 3 DUDH.'),
  (136, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 1', '¿Qué artículo de la DUDH prohíbe la tortura y las penas o tratos crueles, inhumanos o degradantes?', 'El artículo 5', 'El artículo 7', 'El artículo 3', 'El artículo 9', 'A', 'Art. 5 DUDH.'),
  (137, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 1', 'El Convenio Europeo de Derechos Humanos fue firmado:', 'En Estrasburgo, en 1950', 'En Bruselas, en 1957', 'En Roma, en 1950', 'En París, en 1948', 'C', 'Firmado el 4 de noviembre de 1950 en el seno del Consejo de Europa.'),
  (138, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 1', '¿Dónde tiene su sede el Tribunal Europeo de Derechos Humanos?', 'Estrasburgo', 'La Haya', 'Bruselas', 'Luxemburgo', 'A', 'En Luxemburgo está el Tribunal de Justicia de la UE y en La Haya la Corte Internacional de Justicia y la Corte Penal Internacional.'),
  (139, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 1', '¿En qué año ratificó España el Convenio Europeo de Derechos Humanos?', '1986', '1979', '1978', '1982', 'B', 'Instrumento de ratificación de 26 de septiembre de 1979.'),
  (140, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 1', 'El Pacto Internacional de Derechos Civiles y Políticos fue adoptado por la ONU en:', '1948', '1950', '1966', '1976', 'C', 'Adoptado en 1966; entró en vigor en 1976.'),
  (141, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 1', 'La Carta de los Derechos Fundamentales de la UE adquirió el mismo valor jurídico que los Tratados con el:', 'Tratado de Lisboa', 'Tratado de Maastricht', 'Tratado de Niza', 'Tratado de Ámsterdam', 'A', 'Proclamada en Niza (2000), es vinculante desde la entrada en vigor del Tratado de Lisboa (2009).'),
  (142, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 2', 'Según el artículo 10.2 CE, las normas sobre derechos fundamentales se interpretarán de conformidad con:', 'Los Estatutos de Autonomía', 'La Declaración Universal de Derechos Humanos y los tratados internacionales ratificados por España', 'Las leyes orgánicas que los desarrollen', 'La jurisprudencia del Tribunal Supremo', 'B', 'Art. 10.2 CE.'),
  (143, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 2', '¿Dónde tiene su sede el Consejo de Derechos Humanos de las Naciones Unidas?', 'Viena', 'Ginebra', 'La Haya', 'Nueva York', 'B', 'Creado en 2006, sustituyó a la Comisión de Derechos Humanos.'),
  (144, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 2', 'La Corte Penal Internacional, creada por el Estatuto de Roma, tiene su sede en:', 'Estrasburgo', 'Ginebra', 'La Haya', 'Roma', 'C', 'El Estatuto de Roma es de 1998.'),
  (145, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 2', 'Según la DUDH, «nadie podrá ser arbitrariamente detenido, preso ni desterrado». ¿Qué artículo lo recoge?', 'El artículo 11', 'El artículo 13', 'El artículo 5', 'El artículo 9', 'D', 'Art. 9 DUDH.'),
  (146, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 2', 'La presunción de inocencia del acusado de un delito se recoge en el artículo:', '14 de la DUDH', '11 de la DUDH', '9 de la DUDH', '7 de la DUDH', 'B', 'Art. 11.1 DUDH.'),
  (147, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 2', 'El derecho de asilo, en caso de persecución, se recoge en el artículo:', '18 de la DUDH', '14 de la DUDH', '15 de la DUDH', '13 de la DUDH', 'B', 'Art. 14 DUDH. El art. 13 recoge la libertad de circulación y residencia.'),
  (148, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 2', 'La libertad de opinión y de expresión se recoge en el artículo:', '20 de la DUDH', '12 de la DUDH', '19 de la DUDH', '18 de la DUDH', 'C', 'Art. 19 DUDH. El 18 recoge la libertad de pensamiento, conciencia y religión, y el 20 la de reunión y asociación pacíficas.'),
  (149, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 2', 'La Convención de la ONU contra la Tortura y Otros Tratos o Penas Crueles, Inhumanos o Degradantes fue adoptada en:', '1948', '1966', '1984', '1993', 'C', 'Adoptada el 10 de diciembre de 1984.'),
  (150, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 2', '¿Qué institución ejerce en España como Mecanismo Nacional de Prevención de la Tortura?', 'El Defensor del Pueblo', 'El Consejo General del Poder Judicial', 'La Fiscalía General del Estado', 'El Ministerio del Interior', 'A', 'Por atribución de la LO 1/2009.'),
  (151, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Policía Nacional · T2 · Test 2', 'La Convención sobre los Derechos del Niño fue adoptada por la ONU en:', '1999', '1979', '1959', '1989', 'D', 'Adoptada el 20 de noviembre de 1989.'),
  (152, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Simulacro general · Policía Nacional', 'El artículo 3 del Convenio Europeo de Derechos Humanos regula:', 'El derecho a la vida', 'El derecho a un proceso equitativo', 'La prohibición de la tortura', 'La libertad de expresión', 'C', 'Art. 2 CEDH: derecho a la vida; art. 6: proceso equitativo; art. 10: libertad de expresión.'),
  (153, 'Policía Nacional – Escala Básica', 'Tema 2. Los Derechos Humanos', 'Simulacro general · Policía Nacional', '¿Qué instrumentos forman parte de la Carta Internacional de Derechos Humanos? (varias correctas)', 'La Declaración Universal de Derechos Humanos', 'El Pacto Internacional de Derechos Civiles y Políticos', 'La Carta de los Derechos Fundamentales de la UE', 'El Convenio Europeo de Derechos Humanos', 'AB', 'La integran la DUDH, el PIDCP y el PIDESC (con sus protocolos). El CEDH y la Carta de la UE son instrumentos regionales.'),
  (154, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 1', '¿Qué norma regula las Fuerzas y Cuerpos de Seguridad?', 'La Ley Orgánica 4/2015, de 30 de marzo', 'La Ley Orgánica 6/1984, de 24 de mayo', 'La Ley Orgánica 2/1986, de 13 de marzo', 'La Ley Orgánica 9/2015, de 28 de julio', 'C', 'La LO 4/2015 es de seguridad ciudadana, la LO 9/2015 de régimen de personal de la Policía Nacional y la LO 6/1984 de habeas corpus.'),
  (155, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 1', 'La seguridad pública es competencia exclusiva del Estado y su mantenimiento corresponde:', 'A los Ayuntamientos', 'Al Ministerio de Defensa', 'A las Comunidades Autónomas', 'Al Gobierno de la Nación', 'D', 'Art. 1.1 LO 2/1986, sin perjuicio de la participación de CCAA y Corporaciones Locales.'),
  (156, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 1', 'Son Fuerzas y Cuerpos de Seguridad del Estado:', 'La Policía Nacional, la Guardia Civil y las Policías autonómicas', 'La Policía Nacional y la Guardia Civil', 'La Policía Nacional, la Guardia Civil y las Policías Locales', 'Solo la Policía Nacional', 'B', 'Art. 9 LO 2/1986. Las policías autonómicas y locales son Fuerzas y Cuerpos de Seguridad, pero no «del Estado» (art. 2).'),
  (157, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 1', 'La Policía Nacional es:', 'Un Instituto armado de naturaleza civil, dependiente del Ministro del Interior', 'Un cuerpo civil no armado', 'Un cuerpo de naturaleza mixta dependiente de Defensa e Interior', 'Un Instituto armado de naturaleza militar', 'A', 'Art. 9.a LO 2/1986.'),
  (158, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 1', 'Al efectuar una detención, los miembros de las Fuerzas y Cuerpos de Seguridad deberán:', 'Identificarse debidamente como tales', 'Informar primero al Ministerio Fiscal', 'Esperar la presencia de un abogado', 'Solicitar autorización judicial previa', 'A', 'Art. 5.3.a LO 2/1986.'),
  (159, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 1', 'La utilización de las armas por los agentes se rige por los principios de:', 'Necesidad, urgencia y discrecionalidad', 'Congruencia, oportunidad y proporcionalidad', 'Legalidad, jerarquía y eficacia', 'Inmediatez, publicidad y responsabilidad', 'B', 'Art. 5.2.c y d LO 2/1986.'),
  (160, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 1', 'Los miembros de las Fuerzas y Cuerpos de Seguridad deberán intervenir en defensa de la Ley y de la seguridad ciudadana:', 'Solo cuando lo ordene un superior', 'Siempre, en cualquier tiempo y lugar, se hallaren o no de servicio', 'Solo dentro de su demarcación territorial', 'Solo durante su horario de servicio', 'B', 'Art. 5.4 LO 2/1986 (principio de dedicación profesional).'),
  (161, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 1', '¿En qué ámbito territorial ejerce sus funciones la Guardia Civil, con carácter general?', 'En el resto del territorio nacional no asignado a la Policía Nacional y su mar territorial', 'Solo en fronteras, costas y puertos', 'En las capitales de provincia', 'Exclusivamente en zonas rurales de menos de 20.000 habitantes', 'A', 'Art. 11.2.b LO 2/1986. La Policía Nacional actúa en capitales de provincia y en los términos municipales y núcleos urbanos que determine el Gobierno.'),
  (162, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 1', '¿Cuál de estas funciones corresponde con carácter exclusivo a la Policía Nacional?', 'El control de armas y explosivos', 'El resguardo fiscal del Estado', 'La expedición del DNI y de los pasaportes', 'La vigilancia del tráfico en vías interurbanas', 'C', 'Art. 12.1.A LO 2/1986. Las demás corresponden a la Guardia Civil (art. 12.1.B).'),
  (163, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 1', 'El control de las entidades y servicios privados de seguridad corresponde a:', 'La Guardia Civil', 'La Policía Nacional', 'Las Policías Locales', 'El Ministerio de Industria', 'B', 'Art. 12.1.A LO 2/1986.'),
  (164, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 2', 'Las Unidades de Policía Judicial dependen funcionalmente de:', 'Los Jueces, Tribunales y Ministerio Fiscal', 'El Delegado del Gobierno', 'El Ministro del Interior exclusivamente', 'El Consejo General del Poder Judicial', 'A', 'Arts. 29 y 31 LO 2/1986 y art. 126 CE.'),
  (165, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 2', 'Las Policías Locales son:', 'Servicios municipales sin carácter policial', 'Institutos armados de naturaleza militar', 'Cuerpos civiles no armados', 'Institutos armados de naturaleza civil con estructura y organización jerarquizada', 'D', 'Art. 52.1 LO 2/1986.'),
  (166, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 2', '¿Cuál de estas funciones corresponde a las Policías Locales?', 'El control de fronteras', 'Ordenar, señalizar y dirigir el tráfico en el casco urbano', 'La expedición del DNI', 'El resguardo fiscal del Estado', 'B', 'Art. 53.1 LO 2/1986.'),
  (167, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 2', 'Los miembros de las Fuerzas y Cuerpos de Seguridad:', 'Solo pueden hacer huelga los de las Policías Locales', 'Pueden ejercer el derecho de huelga con servicios mínimos', 'No podrán ejercer en ningún caso el derecho de huelga ni acciones sustitutivas', 'Pueden hacer huelga con autorización del Ministro', 'C', 'Art. 6.8 LO 2/1986.'),
  (168, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 2', 'En el ejercicio de sus funciones, los miembros de las Fuerzas y Cuerpos de Seguridad tendrán a todos los efectos legales el carácter de:', 'Personal eventual', 'Agentes de la autoridad', 'Funcionarios de la Administración de Justicia', 'Autoridad', 'B', 'Art. 7.1 LO 2/1986. Cuando se cometa delito de atentado empleando armas de fuego, explosivos u otros medios de agresión de análoga peligrosidad, se les considera autoridad (art. 7.2).'),
  (169, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 2', '¿Quién preside el Consejo de Política de Seguridad?', 'El Ministro del Interior', 'El Secretario de Estado de Seguridad', 'El Presidente del Gobierno', 'El Director General de la Policía', 'A', 'Art. 48 LO 2/1986.'),
  (170, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 2', '¿Qué norma regula el régimen de personal de la Policía Nacional?', 'La Ley Orgánica 2/1986, de 13 de marzo', 'La Ley Orgánica 9/2015, de 28 de julio', 'La Ley 29/2014, de 28 de noviembre', 'El Real Decreto Legislativo 5/2015', 'B', 'La Ley 29/2014 regula el personal de la Guardia Civil.'),
  (171, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 2', '¿Qué categorías integran la Escala Básica de la Policía Nacional?', 'Oficial de Policía y Policía', 'Subinspector y Policía', 'Policía y Agente', 'Inspector y Oficial de Policía', 'A', 'LO 9/2015: Superior (Comisario Principal y Comisario), Ejecutiva (Inspector Jefe e Inspector), Subinspección (Subinspector) y Básica (Oficial de Policía y Policía).'),
  (172, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 2', '¿Qué categorías integran la Escala Ejecutiva de la Policía Nacional?', 'Comisario Principal y Comisario', 'Comisario e Inspector Jefe', 'Inspector Jefe e Inspector', 'Subinspector e Inspector', 'C', 'LO 9/2015.'),
  (173, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Policía Nacional · T3 · Test 2', 'Según la LO 4/2015, la permanencia en dependencias policiales para identificar a una persona no podrá superar:', 'Seis horas', 'Doce horas', 'Veinticuatro horas', 'Tres horas', 'A', 'Art. 16.4 LO 4/2015, de protección de la seguridad ciudadana.'),
  (174, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Simulacro general · Policía Nacional', 'La Policía Nacional se integra orgánicamente en:', 'La Delegación del Gobierno', 'La Dirección General de Tráfico', 'La Dirección General de la Policía', 'La Secretaría General de Instituciones Penitenciarias', 'C', 'Dependiente de la Secretaría de Estado de Seguridad del Ministerio del Interior.'),
  (175, 'Policía Nacional – Escala Básica', 'Tema 3. Las Fuerzas y Cuerpos de Seguridad', 'Simulacro general · Policía Nacional', '¿Cuál de estas funciones corresponde a las Fuerzas y Cuerpos de Seguridad del Estado según el art. 11.1 LO 2/1986?', 'Aprobar ordenanzas de circulación', 'Expedir licencias de actividad', 'Prevenir la comisión de actos delictivos', 'Dictar sentencias en juicios rápidos', 'C', 'Art. 11.1 LO 2/1986.'),
  (176, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 1', 'El Código Penal vigente fue aprobado por:', 'El Real Decreto de 14 de septiembre de 1882', 'La Ley Orgánica 1/2015, de 30 de marzo', 'La Ley Orgánica 10/1995, de 23 de noviembre', 'La Ley Orgánica 5/2000, de 12 de enero', 'C', 'La LO 1/2015 lo reformó; la LO 5/2000 regula la responsabilidad penal del menor y el RD de 1882 aprobó la LECrim.'),
  (177, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 1', 'Según el artículo 10 del Código Penal, son delitos:', 'Las acciones y omisiones dolosas o imprudentes penadas por la ley', 'Las conductas contrarias a la moral', 'Solo las acciones dolosas penadas por la ley', 'Las infracciones administrativas graves', 'A', 'Art. 10 CP.'),
  (178, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 1', 'Las acciones u omisiones imprudentes:', 'Se castigan siempre con la mitad de la pena', 'Se castigan solo si causan la muerte', 'Solo se castigan cuando expresamente lo disponga la ley', 'Nunca se castigan penalmente', 'C', 'Art. 12 CP.'),
  (179, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 1', 'Según su gravedad, los delitos se clasifican en:', 'Delitos y faltas', 'Graves, menos graves y leves', 'Muy graves, graves y leves', 'Graves, menos graves y faltas', 'B', 'Art. 13 CP. Las faltas desaparecieron con la LO 1/2015.'),
  (180, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 1', 'Es pena grave la prisión:', 'De tres meses a cinco años', 'Superior a cinco años', 'Superior a tres años', 'Superior a dos años', 'B', 'Art. 33.2.a CP.'),
  (181, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 1', 'Es pena menos grave la prisión:', 'De tres meses hasta cinco años', 'De seis meses a cinco años', 'Inferior a tres meses', 'De un mes a tres años', 'A', 'Art. 33.3.a CP.'),
  (182, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 1', 'La pena de prisión tendrá, con carácter general, una duración mínima de:', 'Un mes', 'Quince días', 'Tres meses', 'Seis meses', 'C', 'Art. 36.2 CP: mínimo tres meses y máximo veinte años, salvo excepciones.'),
  (183, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 1', '¿Qué ley introdujo la prisión permanente revisable?', 'La Ley Orgánica 10/1995', 'La Ley Orgánica 5/2010', 'La Ley Orgánica 7/2003', 'La Ley Orgánica 1/2015', 'D', 'Art. 33.2.a CP, tras la reforma de 2015.'),
  (184, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 1', 'Según el artículo 15 CP, son punibles:', 'La tentativa solo en delitos leves', 'Solo el delito consumado', 'El delito consumado y la tentativa de delito', 'Los actos preparatorios en todo caso', 'C', 'Art. 15 CP.'),
  (185, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 1', 'Según el artículo 28 CP, también serán considerados autores:', 'Quienes conocen el delito y no lo denuncian', 'Los que inducen directamente a otro u otros a ejecutarlo', 'Los encubridores', 'Los cómplices', 'B', 'Art. 28 CP: también los cooperadores necesarios.'),
  (186, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 2', 'Son cómplices los que, no hallándose comprendidos entre los autores:', 'Se benefician del producto del delito', 'Ocultan el cuerpo del delito', 'Cooperan a la ejecución del hecho con actos anteriores o simultáneos', 'Ayudan al culpable a eludir la investigación', 'C', 'Art. 29 CP.'),
  (187, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 2', '¿Cuál de las siguientes es una circunstancia eximente?', 'El parentesco', 'La confesión de la infracción', 'El miedo insuperable', 'La reincidencia', 'C', 'Art. 20.6 CP. La reincidencia es agravante, la confesión atenuante y el parentesco circunstancia mixta.'),
  (188, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 2', '¿Cuál NO es requisito de la legítima defensa?', 'Falta de provocación suficiente por parte del defensor', 'Que el defensor sea agente de la autoridad', 'Agresión ilegítima', 'Necesidad racional del medio empleado', 'B', 'Art. 20.4 CP.'),
  (189, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 2', '¿Cuál de las siguientes es una circunstancia agravante?', 'La confesión de la infracción a las autoridades', 'Ejecutar el hecho con abuso de superioridad', 'La reparación del daño', 'La dilación extraordinaria e indebida del procedimiento', 'B', 'Art. 22.2 CP. Las demás son atenuantes (art. 21).'),
  (190, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 2', 'El parentesco (art. 23 CP) es una circunstancia:', 'Mixta: puede atenuar o agravar según la naturaleza, motivos y efectos del delito', 'Siempre atenuante', 'Siempre agravante', 'Eximente completa', 'A', 'Art. 23 CP.'),
  (191, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 2', 'Los menores de dieciocho años que cometan un hecho delictivo responderán con arreglo a:', 'La Ley Orgánica 5/2000, reguladora de la responsabilidad penal de los menores', 'No responden en ningún caso', 'El Código Penal con penas reducidas a la mitad', 'El Código Civil', 'A', 'Art. 19 CP.'),
  (192, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 2', '¿Pueden las personas jurídicas ser penalmente responsables en España?', 'Sí, en los supuestos previstos en el Código Penal', 'Solo en delitos fiscales y siempre', 'No, nunca', 'Solo si son entidades públicas', 'A', 'Art. 31 bis CP.'),
  (193, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 2', 'Los delitos leves prescriben:', 'A los dos años', 'Al año', 'A los seis meses', 'A los tres meses', 'B', 'Art. 131.1 CP (también los de injurias y calumnias).'),
  (194, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 2', '¿Cuál de los siguientes delitos NO prescribe?', 'El homicidio imprudente', 'El robo con violencia', 'El genocidio', 'La estafa', 'C', 'Art. 131.3 CP: lesa humanidad, genocidio, delitos contra personas y bienes protegidos en caso de conflicto armado (salvo art. 614) y terrorismo con resultado de muerte.'),
  (195, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Policía Nacional · T4 · Test 2', 'El robo se distingue del hurto en que requiere:', 'Fuerza en las cosas o violencia o intimidación en las personas', 'Que se cometa de noche', 'Que el valor de lo sustraído supere 400 euros', 'Que intervengan dos o más personas', 'A', 'Art. 237 CP.'),
  (196, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Simulacro general · Policía Nacional', 'El hurto es delito leve cuando la cuantía de lo sustraído no excede de:', '500 euros', '300 euros', '400 euros', '1.000 euros', 'C', 'Art. 234.2 CP, salvo que concurra alguna circunstancia del art. 235.'),
  (197, 'Policía Nacional – Escala Básica', 'Tema 4. Derecho Penal: el delito y las penas', 'Simulacro general · Policía Nacional', '¿Cuáles de las siguientes son circunstancias atenuantes del art. 21 CP? (varias correctas)', 'La reparación del daño causado a la víctima', 'La dilación extraordinaria e indebida en la tramitación del procedimiento', 'El abuso de confianza', 'La reincidencia', 'AB', 'Art. 21.5 y 21.6 CP. La reincidencia y el abuso de confianza son agravantes (art. 22).'),
  (198, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 1', 'La Ley de Enjuiciamiento Criminal fue aprobada por:', 'La Ley Orgánica 6/1985', 'La Ley Orgánica 10/1995', 'El Real Decreto de 14 de septiembre de 1882', 'La Ley 1/2000, de 7 de enero', 'C', 'La LO 6/1985 es del Poder Judicial y la Ley 1/2000 de Enjuiciamiento Civil.'),
  (199, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 1', 'Según el artículo 490 LECrim, cualquier persona puede detener:', 'A quien se niegue a identificarse', 'A cualquier persona sospechosa', 'Al delincuente in fraganti', 'A quien cometa una infracción administrativa', 'C', 'Art. 490 LECrim: también al que intentare cometer un delito en el momento de ir a cometerlo, entre otros supuestos.'),
  (200, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 1', 'En el plazo máximo de 72 horas desde la detención, el detenido deberá:', 'Prestar declaración ante el Fiscal', 'Ser puesto en libertad o a disposición de la autoridad judicial', 'Ser trasladado a un centro penitenciario', 'Ser juzgado por un juicio rápido', 'B', 'Art. 17.2 CE y art. 520.1 LECrim.'),
  (201, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 1', '¿Cuál de los siguientes NO es un derecho del detenido del art. 520 LECrim?', 'Elegir el centro de detención', 'Ser asistido gratuitamente por un intérprete', 'Guardar silencio', 'Designar abogado', 'A', 'Art. 520.2 LECrim.'),
  (202, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 1', 'El abogado designado deberá acudir al centro de detención:', 'Antes de 72 horas', 'Con la máxima premura, dentro del plazo máximo de tres horas desde la recepción del encargo', 'En el plazo de 24 horas', 'En el plazo de 8 horas', 'B', 'Art. 520.5 LECrim.'),
  (203, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 1', 'El detenido puede renunciar a la asistencia letrada cuando su detención lo fuere por hechos susceptibles de tipificarse exclusivamente como:', 'Delitos leves de cualquier clase', 'Delitos contra el orden público', 'Delitos de hurto', 'Delitos contra la seguridad vial', 'D', 'Art. 520.8 LECrim.'),
  (204, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 1', '¿Qué norma regula el procedimiento de habeas corpus?', 'La Ley Orgánica 6/1984, de 24 de mayo', 'La Ley Orgánica 2/1986, de 13 de marzo', 'La Ley Orgánica 5/2000, de 12 de enero', 'La Ley Orgánica 4/2015, de 30 de marzo', 'A', 'LO 6/1984.'),
  (205, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 1', 'Es competente para conocer del habeas corpus:', 'El Tribunal Constitucional', 'El Juez de lo Penal del domicilio del detenido', 'La Audiencia Provincial', 'El Juez de Instrucción del lugar en que se encuentre la persona privada de libertad', 'D', 'Art. 2 LO 6/1984. Si no consta, el del lugar de la detención y, en su defecto, el de las últimas noticias.'),
  (206, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 1', 'Desde que se dicta el auto de incoación, el procedimiento de habeas corpus debe resolverse en:', 'Cuarenta y ocho horas', 'Diez días', 'Setenta y dos horas', 'Veinticuatro horas', 'D', 'Art. 7 LO 6/1984.'),
  (207, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 1', '¿Quién puede iniciar de oficio el procedimiento de habeas corpus?', 'El abogado del detenido', 'El Juez competente', 'El Delegado del Gobierno', 'El jefe de la dependencia policial', 'B', 'Art. 3 LO 6/1984. También pueden instarlo el privado de libertad, sus familiares, el Ministerio Fiscal y el Defensor del Pueblo.'),
  (208, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 2', 'Los atestados redactados por los funcionarios de Policía Judicial se considerarán a efectos legales:', 'Denuncias', 'Sentencias', 'Querellas', 'Pruebas plenas', 'A', 'Art. 297 LECrim.'),
  (209, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 2', 'El que presenciare la perpetración de cualquier delito público está obligado a:', 'Ponerlo inmediatamente en conocimiento del Juez, Fiscal, Tribunal o funcionario de policía más próximo', 'Presentar querella en el plazo de diez días', 'Comunicarlo únicamente si es víctima', 'Detener al autor en todo caso', 'A', 'Art. 259 LECrim.'),
  (210, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 2', '¿Quiénes NO están obligados a denunciar?', 'Los parientes colaterales consanguíneos o afines del delincuente hasta el segundo grado inclusive', 'Los funcionarios públicos que conozcan el delito por su cargo', 'Los vecinos del lugar del delito', 'Los testigos presenciales', 'A', 'Art. 261 LECrim: tampoco el cónyuge ni los ascendientes y descendientes.'),
  (211, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 2', 'Todos los ciudadanos españoles, hayan sido o no ofendidos por el delito, pueden querellarse ejercitando:', 'La acusación privada exclusivamente', 'La acción civil', 'La acción popular', 'La acción particular', 'C', 'Art. 270 LECrim y art. 125 CE.'),
  (212, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 2', 'El procedimiento para el enjuiciamiento rápido se aplica, entre otros requisitos, a delitos castigados con pena privativa de libertad que no exceda de:', 'Nueve años', 'Dos años', 'Cinco años', 'Tres años', 'C', 'Art. 795 LECrim.'),
  (213, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 2', '¿Qué órgano enjuicia los delitos castigados con pena privativa de libertad no superior a cinco años?', 'El Tribunal Superior de Justicia', 'El Juzgado de Instrucción', 'La Audiencia Provincial', 'El Juzgado de lo Penal', 'D', 'Art. 14.3 LECrim.'),
  (214, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 2', 'La resolución judicial que acuerda la entrada y registro en un domicilio adopta la forma de:', 'Sentencia', 'Diligencia de ordenación', 'Auto motivado', 'Providencia', 'C', 'Art. 558 LECrim.'),
  (215, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 2', 'La información de derechos al detenido se le facilitará:', 'Únicamente en castellano', 'Solo verbalmente', 'Por escrito, en un lenguaje sencillo y accesible y en una lengua que comprenda', 'Solo si la solicita expresamente', 'C', 'Art. 520.2 LECrim.'),
  (216, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 2', 'La detención de un menor no podrá durar más del tiempo estrictamente necesario y, en todo caso, deberá ser puesto en libertad o a disposición del Ministerio Fiscal en un plazo máximo de:', 'Doce horas', 'Cuarenta y ocho horas', 'Veinticuatro horas', 'Setenta y dos horas', 'C', 'Art. 17.4 LO 5/2000, de responsabilidad penal del menor.'),
  (217, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Policía Nacional · T5 · Test 2', 'Para acordar la prisión provisional, con carácter general, el delito debe estar castigado con pena cuyo máximo sea igual o superior a:', 'Tres meses de prisión', 'Dos años de prisión', 'Cinco años de prisión', 'Un año de prisión', 'B', 'Art. 503.1.1.º LECrim, salvo antecedentes penales del investigado.'),
  (218, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Simulacro general · Policía Nacional', 'Desde la reforma de la Ley 41/2015, la persona sometida a una investigación penal se denomina en la fase de instrucción:', 'Investigado', 'Imputado', 'Procesado', 'Acusado', 'A', 'Tras la conclusión de la instrucción se emplea el término «encausado».'),
  (219, 'Policía Nacional – Escala Básica', 'Tema 5. La detención y el habeas corpus', 'Simulacro general · Policía Nacional', '¿Cuáles de las siguientes personas pueden instar el procedimiento de habeas corpus? (varias correctas)', 'El agente que practicó la detención', 'Cualquier ciudadano sin relación con el detenido', 'El Defensor del Pueblo', 'El Ministerio Fiscal', 'CD', 'Art. 3 LO 6/1984: el privado de libertad, su cónyuge o pareja, descendientes, ascendientes, hermanos, representantes legales, el Ministerio Fiscal, el Defensor del Pueblo y el Juez de oficio.'),
  (220, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 1', 'La Carta de las Naciones Unidas se firmó en:', 'París, el 10 de diciembre de 1948', 'San Francisco, el 26 de junio de 1945', 'Ginebra, el 26 de junio de 1946', 'Nueva York, el 24 de octubre de 1945', 'B', 'Entró en vigor el 24 de octubre de 1945, fecha que se celebra como Día de las Naciones Unidas.'),
  (221, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 1', 'El Día Internacional de los Derechos Humanos se celebra el:', '10 de diciembre', '24 de octubre', '8 de marzo', '20 de noviembre', 'A', 'Conmemora la adopción de la DUDH el 10/12/1948.'),
  (222, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 1', 'La Oficina del Alto Comisionado de las Naciones Unidas para los Derechos Humanos tiene su sede en:', 'Viena', 'Ginebra', 'Estrasburgo', 'Nueva York', 'B', 'OACNUDH, con sede en Ginebra.'),
  (223, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 1', 'La llamada Carta Internacional de Derechos Humanos está formada por:', 'La Carta de la ONU y la DUDH', 'La DUDH y la Carta de los Derechos Fundamentales de la UE', 'La DUDH y el Convenio Europeo de Derechos Humanos', 'La DUDH, el Pacto Internacional de Derechos Civiles y Políticos y el Pacto Internacional de Derechos Económicos, Sociales y Culturales', 'D', 'Junto con los protocolos facultativos de los Pactos.'),
  (224, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 1', 'El Consejo de Europa, en cuyo seno se adoptó el CEDH, se fundó en:', '1957', '1945', '1950', '1949', 'D', 'Por el Tratado de Londres de 5 de mayo de 1949; tiene su sede en Estrasburgo.'),
  (225, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 1', 'Tras el Protocolo n.º 15, el plazo para presentar una demanda ante el TEDH una vez agotados los recursos internos es de:', 'Un año', 'Cuatro meses', 'Seis meses', 'Tres meses', 'B', 'El plazo se redujo de seis a cuatro meses con efectos desde el 1 de febrero de 2022.'),
  (226, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 1', '«Nadie estará sometido a esclavitud ni a servidumbre» se recoge en el artículo:', '8 de la DUDH', '4 de la DUDH', '5 de la DUDH', '3 de la DUDH', 'B', 'Art. 4 DUDH.'),
  (227, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 1', 'El derecho a la educación, con instrucción elemental obligatoria y gratuita, se recoge en el artículo:', '27 de la DUDH', '25 de la DUDH', '23 de la DUDH', '26 de la DUDH', 'D', 'Art. 26 DUDH. El art. 23 recoge el derecho al trabajo.'),
  (228, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 1', 'El Pacto Internacional de Derechos Económicos, Sociales y Culturales se adoptó en:', '1950', '1976', '1966', '1948', 'C', 'Adoptado en 1966, junto al PIDCP; entraron en vigor en 1976.'),
  (229, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 1', 'La Convención sobre la eliminación de todas las formas de discriminación contra la mujer (CEDAW) se adoptó en:', '1979', '1993', '1989', '1966', 'A', 'Adoptada por la Asamblea General de la ONU el 18 de diciembre de 1979.'),
  (230, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 2', '¿En qué año se adoptó la Convención sobre el Estatuto de los Refugiados?', '1967', '1951', '1984', '1948', 'B', 'Convención de Ginebra de 1951, completada por el Protocolo de Nueva York de 1967.'),
  (231, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 2', 'El Convenio del Consejo de Europa sobre prevención y lucha contra la violencia contra las mujeres y la violencia doméstica se conoce como:', 'Convenio de Estambul (2011)', 'Convenio de Lanzarote (2007)', 'Convenio de Budapest (2001)', 'Convenio de Oviedo (1997)', 'A', 'Lanzarote: protección de menores contra la explotación sexual; Budapest: ciberdelincuencia; Oviedo: biomedicina.'),
  (232, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 2', '¿Qué organismo de la ONU se ocupa de la protección de los refugiados?', 'OIT', 'ACNUR', 'UNICEF', 'UNESCO', 'B', 'Alto Comisionado de las Naciones Unidas para los Refugiados.'),
  (233, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 2', 'El derecho a un proceso equitativo se recoge en el artículo:', '6 del Convenio Europeo de Derechos Humanos', '5 del CEDH', '13 del CEDH', '8 del CEDH', 'A', 'Art. 5: libertad y seguridad; art. 8: vida privada y familiar; art. 13: recurso efectivo.'),
  (234, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 2', 'El Protocolo n.º 13 al CEDH se refiere a:', 'La protección de datos personales', 'La reducción del plazo de demanda', 'La abolición de la pena de muerte en cualquier circunstancia', 'La prohibición general de discriminación', 'C', 'El Protocolo n.º 6 la abolió en tiempo de paz; el n.º 13 (2002), en toda circunstancia.'),
  (235, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 2', 'El Defensor del Pueblo es elegido por las Cortes Generales para un periodo de:', 'Nueve años', 'Seis años', 'Cinco años', 'Cuatro años', 'C', 'Art. 2.1 LO 3/1981, del Defensor del Pueblo.'),
  (236, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 2', 'Según el artículo 10.1 CE, son fundamento del orden político y de la paz social:', 'La libertad, la justicia, la igualdad y el pluralismo político', 'La dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás', 'La soberanía nacional y la separación de poderes', 'La unidad de la Nación y la solidaridad entre territorios', 'B', 'Art. 10.1 CE.'),
  (237, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 2', 'Según el artículo 13.3 CE, la extradición:', 'Se concede siempre que la solicite un Estado miembro de la ONU', 'Solo se concede por delitos de terrorismo', 'Requiere autorización del Congreso', 'No se concede por delitos políticos, no considerándose como tales los actos de terrorismo', 'D', 'Art. 13.3 CE: solo se concede en cumplimiento de un tratado o de la ley, atendiendo al principio de reciprocidad.'),
  (238, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 2', '¿Dónde tiene su sede la Corte Interamericana de Derechos Humanos?', 'Ciudad de México', 'Washington', 'San José de Costa Rica', 'Buenos Aires', 'C', 'Creada por la Convención Americana sobre Derechos Humanos.'),
  (239, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Guardia Civil · T1 · Test 2', 'La Convención Americana sobre Derechos Humanos (Pacto de San José) se adoptó en:', '1948', '1979', '1959', '1969', 'D', 'Adoptada el 22 de noviembre de 1969.'),
  (240, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Simulacro general · Guardia Civil', 'Según la DUDH, toda persona tiene derecho, en caso de persecución, a buscar asilo y a disfrutar de él en cualquier país. ¿Qué artículo lo recoge?', 'El artículo 14', 'El artículo 9', 'El artículo 13', 'El artículo 15', 'A', 'Art. 14 DUDH.'),
  (241, 'Guardia Civil – Cabos y Guardias', 'Tema 1. Derechos Humanos y organismos internacionales', 'Simulacro general · Guardia Civil', '¿Cuáles de los siguientes son instrumentos del Consejo de Europa? (varias correctas)', 'La Declaración Universal de Derechos Humanos', 'El Convenio de Estambul', 'El Convenio Europeo de Derechos Humanos', 'La Carta de las Naciones Unidas', 'BC', 'La DUDH y la Carta de la ONU son instrumentos de las Naciones Unidas.'),
  (242, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 1', '¿Qué ley regula la igualdad efectiva de mujeres y hombres?', 'La Ley Orgánica 3/2007, de 22 de marzo', 'La Ley 15/2022, de 12 de julio', 'La Ley Orgánica 1/2004, de 28 de diciembre', 'La Ley Orgánica 10/2022, de 6 de septiembre', 'A', 'La LO 1/2004 regula la protección integral contra la violencia de género.'),
  (243, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 1', '¿Qué ley establece las Medidas de Protección Integral contra la Violencia de Género?', 'La Ley Orgánica 3/2007, de 22 de marzo', 'La Ley 27/2003, de 31 de julio', 'La Ley Orgánica 1/2004, de 28 de diciembre', 'La Ley Orgánica 8/2021, de 4 de junio', 'C', 'La Ley 27/2003 reguló la orden de protección de las víctimas de violencia doméstica.'),
  (244, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 1', 'Según el artículo 14 CE, NO puede prevalecer discriminación alguna por razón de:', 'Sexo, salvo en el acceso a la función pública', 'Nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social', 'Nacionalidad exclusivamente', 'Únicamente sexo y raza', 'B', 'Art. 14 CE.'),
  (245, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 1', 'La situación en que se encuentra una persona que es tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable se denomina:', 'Discriminación directa por razón de sexo', 'Acoso por razón de sexo', 'Discriminación indirecta por razón de sexo', 'Acción positiva', 'A', 'Art. 6.1 LO 3/2007.'),
  (246, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 1', 'La disposición, criterio o práctica aparentemente neutros que pone a personas de un sexo en desventaja particular respecto de las del otro se denomina:', 'Composición equilibrada', 'Discriminación directa', 'Acoso sexual', 'Discriminación indirecta por razón de sexo', 'D', 'Art. 6.2 LO 3/2007, salvo que pueda justificarse objetivamente.'),
  (247, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 1', 'Se entiende por composición equilibrada la presencia de mujeres y hombres de forma que las personas de cada sexo:', 'Sean exactamente el 50 %', 'No superen el 60 % ni sean menos del 40 %', 'No superen el 55 % ni sean menos del 45 %', 'No superen el 70 % ni sean menos del 30 %', 'B', 'Disposición adicional primera de la LO 3/2007.'),
  (248, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 1', 'Cualquier comportamiento, verbal o físico, de naturaleza sexual que tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona constituye:', 'Acoso sexual', 'Discriminación indirecta', 'Acoso por razón de sexo', 'Violencia de género en todo caso', 'A', 'Art. 7.1 LO 3/2007.'),
  (249, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 1', 'Las empresas están obligadas a elaborar y aplicar un plan de igualdad cuando tengan:', 'Más de diez personas trabajadoras', 'Cien o más personas trabajadoras', 'Doscientas cincuenta o más personas trabajadoras', 'Cincuenta o más personas trabajadoras', 'D', 'Art. 45.2 LO 3/2007, tras la reforma del RDL 6/2019.'),
  (250, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 1', 'Según la LO 1/2004, la violencia de género es la ejercida sobre las mujeres por parte de:', 'Cualquier persona de su entorno familiar', 'Solo sus cónyuges con convivencia', 'Cualquier persona, con independencia de su relación', 'Quienes sean o hayan sido sus cónyuges o estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia', 'D', 'Art. 1.1 LO 1/2004.'),
  (251, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 1', '¿Qué órganos judiciales especializados creó la LO 1/2004?', 'Los Juzgados de Vigilancia Penitenciaria', 'Los Juzgados de Familia', 'Las Fiscalías de Menores', 'Los Juzgados de Violencia sobre la Mujer', 'D', 'Título V de la LO 1/2004.'),
  (252, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 2', 'Los Juzgados de Violencia sobre la Mujer tienen competencias en el orden:', 'Penal y contencioso-administrativo', 'Solo civil', 'Solo penal', 'Penal y civil', 'D', 'Conocen de las causas penales y de determinados asuntos civiles relacionados (familia, filiación, custodia…).'),
  (253, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 2', 'La orden de protección de las víctimas de violencia doméstica y de género se regula en:', 'El artículo 153 del Código Penal', 'El artículo 544 ter de la Ley de Enjuiciamiento Criminal', 'La Ley Orgánica 3/2007', 'El artículo 520 de la Ley de Enjuiciamiento Criminal', 'B', 'Introducido por la Ley 27/2003.'),
  (254, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 2', '¿Cuál es el teléfono de información y asesoramiento a víctimas de violencia de género?', '091', '016', '062', '112', 'B', 'Es gratuito y no deja rastro en la factura. El 062 es el teléfono de la Guardia Civil y el 091 el de la Policía Nacional.'),
  (255, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 2', 'El Día Internacional de la Eliminación de la Violencia contra la Mujer se celebra el:', '10 de diciembre', '8 de marzo', '11 de febrero', '25 de noviembre', 'D', 'El 8 de marzo es el Día Internacional de la Mujer.'),
  (256, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 2', '¿Cómo se denominan los equipos especializados de la Guardia Civil en la atención a la mujer y al menor?', 'UCO', 'UFAM', 'GRS', 'EMUME', 'D', 'UFAM son las Unidades de Atención a la Familia y Mujer de la Policía Nacional.'),
  (257, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 2', 'El Sistema de Seguimiento Integral en los casos de Violencia de Género (VioGén) depende de:', 'El Ministerio de Justicia', 'El Consejo General del Poder Judicial', 'Las Comunidades Autónomas', 'El Ministerio del Interior', 'D', 'Funciona desde 2007 y lo utilizan las Fuerzas y Cuerpos de Seguridad para valorar el riesgo.'),
  (258, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 2', 'El Pacto de Estado contra la Violencia de Género fue aprobado en:', '2021', '2004', '2007', '2017', 'D', 'Aprobado por el Congreso de los Diputados en septiembre de 2017.'),
  (259, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 2', 'Según la LO 3/2007, el principio de igualdad de trato y oportunidades entre mujeres y hombres informará:', 'Con carácter transversal la actuación de todos los poderes públicos', 'Únicamente las relaciones laborales', 'Solo la legislación penal', 'Solo la actuación del Ministerio de Igualdad', 'A', 'Art. 15 LO 3/2007.'),
  (260, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 2', 'Las víctimas de violencia de género tienen derecho, entre otros, a:', 'La asistencia jurídica gratuita inmediata', 'Un abogado de libre elección pagado por el agresor en todo caso', 'La concesión automática de la nacionalidad', 'La exención de todos los impuestos', 'A', 'Art. 20 LO 1/2004 y Ley 1/1996 de asistencia jurídica gratuita.'),
  (261, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Guardia Civil · T2 · Test 2', 'Según el artículo 9.2 CE, corresponde a los poderes públicos:', 'Aprobar planes de igualdad en todas las empresas', 'Promover las condiciones para que la libertad y la igualdad del individuo y de los grupos sean reales y efectivas', 'Sancionar cualquier desigualdad económica', 'Garantizar la igualdad formal exclusivamente', 'B', 'Art. 9.2 CE (igualdad material).'),
  (262, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Simulacro general · Guardia Civil', 'El artículo 35 CE reconoce el derecho al trabajo y a una remuneración suficiente:', 'Únicamente a los mayores de 18 años', 'Sin que en ningún caso pueda hacerse discriminación por razón de sexo', 'Solo para los trabajadores del sector público', 'Con preferencia de los cabezas de familia', 'B', 'Art. 35.1 CE.'),
  (263, 'Guardia Civil – Cabos y Guardias', 'Tema 2. Igualdad efectiva y violencia de género', 'Simulacro general · Guardia Civil', '¿Cuáles de los siguientes son unidades o sistemas de atención a víctimas de violencia de género? (varias correctas)', 'El Sistema VioGén', 'La Unidad Central Operativa (UCO)', 'Los EMUME de la Guardia Civil', 'El Servicio de Protección de la Naturaleza (SEPRONA)', 'AC', 'La UCO investiga delincuencia organizada y grave; el SEPRONA protege la naturaleza y el medio ambiente.'),
  (264, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 1', '¿Cuántos miembros componen el Tribunal Constitucional?', 'Nueve', 'Quince', 'Doce', 'Veinte', 'C', 'Art. 159.1 CE: nombrados por el Rey.'),
  (265, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 1', 'Los magistrados del Tribunal Constitucional son designados por un periodo de:', 'Nueve años, renovándose por terceras partes cada tres', 'Seis años, renovándose por mitades cada tres', 'Doce años', 'Cinco años, coincidiendo con el CGPJ', 'A', 'Art. 159.3 CE.'),
  (266, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 1', '¿Cuántos magistrados del Tribunal Constitucional se nombran a propuesta del Gobierno?', 'Cuatro', 'Dos', 'Tres', 'Uno', 'B', 'Art. 159.1 CE: 4 a propuesta del Congreso, 4 del Senado, 2 del Gobierno y 2 del CGPJ.'),
  (267, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 1', 'Están legitimados para interponer el recurso de inconstitucionalidad, entre otros:', 'Cualquier ciudadano', 'Diez Diputados', 'Cincuenta Diputados', 'El Fiscal General del Estado', 'C', 'Art. 162.1.a CE: Presidente del Gobierno, Defensor del Pueblo, 50 Diputados, 50 Senadores y órganos colegiados ejecutivos y Asambleas de las CCAA.'),
  (268, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 1', 'Están legitimados para interponer el recurso de amparo:', 'Cincuenta Diputados o Senadores', 'Solo el Defensor del Pueblo', 'Únicamente los ciudadanos españoles mayores de edad', 'Toda persona natural o jurídica que invoque un interés legítimo, el Defensor del Pueblo y el Ministerio Fiscal', 'D', 'Art. 162.1.b CE.'),
  (269, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 1', 'Según el artículo 117.1 CE, la justicia emana del pueblo y se administra en nombre de:', 'Las Cortes Generales', 'El Rey', 'El Consejo General del Poder Judicial', 'El Estado', 'B', 'Por Jueces y Magistrados independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley.'),
  (270, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 1', 'El Consejo General del Poder Judicial está integrado por:', 'El Presidente del Tribunal Supremo y veinte miembros nombrados por un periodo de cinco años', 'El Ministro de Justicia y quince vocales', 'Doce miembros nombrados por nueve años', 'Veinte miembros elegidos por el Gobierno', 'A', 'Art. 122.3 CE.'),
  (271, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 1', 'El Tribunal Supremo es el órgano jurisdiccional superior en todos los órdenes:', 'Salvo en el orden militar', 'Salvo en las Comunidades Autónomas con Tribunal Superior propio', 'Sin excepción alguna', 'Salvo lo dispuesto en materia de garantías constitucionales', 'D', 'Art. 123.1 CE.'),
  (272, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 1', 'El Fiscal General del Estado es nombrado por el Rey:', 'A propuesta del Tribunal Supremo', 'A propuesta del Congreso de los Diputados', 'A propuesta del CGPJ', 'A propuesta del Gobierno, oído el Consejo General del Poder Judicial', 'D', 'Art. 124.4 CE.'),
  (273, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 1', '¿Qué institución permite a los ciudadanos participar en la Administración de Justicia según el art. 125 CE?', 'Los Juzgados de Paz exclusivamente', 'El Jurado', 'El Ministerio Fiscal', 'El Defensor del Pueblo', 'B', 'Art. 125 CE: también mediante la acción popular y los tribunales consuetudinarios y tradicionales.'),
  (274, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 2', 'El gobierno y la administración de los municipios corresponde a:', 'Los Ayuntamientos, integrados por los Alcaldes y los Concejales', 'Los Delegados del Gobierno', 'Los Plenos de las Comunidades Autónomas', 'Las Diputaciones Provinciales', 'A', 'Art. 140 CE.'),
  (275, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 2', 'Según el art. 140 CE, los Alcaldes serán elegidos:', 'Por la Diputación Provincial', 'Siempre directamente por los vecinos', 'Por el Gobierno de la Comunidad Autónoma', 'Por los Concejales o por los vecinos', 'D', 'Art. 140 CE. Los Concejales se eligen por sufragio universal, igual, libre, directo y secreto.'),
  (276, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 2', 'La provincia es:', 'Una división administrativa sin personalidad jurídica', 'Una agrupación de Comunidades Autónomas', 'Una entidad local con personalidad jurídica propia, determinada por la agrupación de municipios', 'Un órgano periférico de la Administración del Estado exclusivamente', 'C', 'Art. 141.1 CE.'),
  (277, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 2', 'En los archipiélagos, las islas tendrán además su administración propia en forma de:', 'Mancomunidades', 'Comarcas', 'Cabildos o Consejos', 'Diputaciones forales', 'C', 'Art. 141.4 CE: Cabildos en Canarias y Consejos Insulares en Baleares.'),
  (278, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 2', 'La norma institucional básica de cada Comunidad Autónoma es:', 'Su Estatuto de Autonomía', 'El Reglamento de su Asamblea', 'Su ley de presupuestos', 'La Constitución', 'A', 'Art. 147.1 CE.'),
  (279, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 2', '¿Cuál de las siguientes materias es competencia exclusiva del Estado según el art. 149.1 CE?', 'Ferias interiores', 'Promoción y ordenación del turismo en su ámbito territorial', 'Defensa y Fuerzas Armadas', 'Artesanía', 'C', 'Art. 149.1.4.ª CE. Las demás son materias que pueden asumir las CCAA (art. 148).'),
  (280, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 2', 'Para adoptar las medidas del artículo 155 CE frente a una Comunidad Autónoma se requiere:', 'La declaración del estado de excepción', 'El dictamen favorable del Tribunal Constitucional', 'La aprobación por mayoría absoluta del Senado', 'La aprobación por mayoría absoluta del Congreso', 'C', 'Art. 155.1 CE, previo requerimiento al Presidente de la Comunidad Autónoma.'),
  (281, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 2', '¿En qué parte de la Constitución se regulan las Fuerzas Armadas?', 'En el Título I', 'En el Título VIII', 'En el Título IV', 'En el Título Preliminar (art. 8)', 'D', 'Art. 8 CE: Ejército de Tierra, Armada y Ejército del Aire.'),
  (282, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 2', 'Según el artículo 30 CE, los españoles tienen:', 'El derecho y el deber de defender a España', 'Solo el deber de defender a España', 'El derecho a no defender a España', 'La obligación de realizar el servicio militar', 'A', 'Art. 30.1 CE.'),
  (283, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Guardia Civil · T3 · Test 2', 'El ejercicio de la potestad jurisdiccional, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente a:', 'El Ministerio de Justicia', 'El Consejo General del Poder Judicial', 'El Tribunal Constitucional', 'Los Juzgados y Tribunales determinados por las leyes', 'D', 'Art. 117.3 CE.'),
  (284, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Simulacro general · Guardia Civil', 'Según el artículo 104.2 CE, las funciones, principios básicos de actuación y estatutos de las Fuerzas y Cuerpos de Seguridad se determinarán por:', 'Una ley ordinaria', 'Los Estatutos de Autonomía', 'Un real decreto', 'Una ley orgánica', 'D', 'Desarrollado por la LO 2/1986, de Fuerzas y Cuerpos de Seguridad.'),
  (285, 'Guardia Civil – Cabos y Guardias', 'Tema 3. La Constitución: Poder Judicial, Tribunal Constitucional y organización territorial', 'Simulacro general · Guardia Civil', '¿Quiénes proponen magistrados del Tribunal Constitucional? (varias correctas)', 'El Defensor del Pueblo', 'El Consejo General del Poder Judicial', 'El Tribunal Supremo', 'El Senado', 'BD', 'Art. 159.1 CE: Congreso (4), Senado (4), Gobierno (2) y CGPJ (2).'),
  (286, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 1', '¿En qué año se fundó la Guardia Civil?', '1812', '1900', '1844', '1868', 'C', 'Creada en 1844 bajo el reinado de Isabel II.'),
  (287, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 1', '¿Quién fue el fundador y primer Director General de la Guardia Civil?', 'El General Espartero', 'El Duque de Ahumada', 'El Duque de Rivas', 'El General Narváez', 'B', 'Francisco Javier Girón y Ezpeleta, II Duque de Ahumada.'),
  (288, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 1', 'La Guardia Civil es:', 'Una rama de las Fuerzas Armadas dependiente solo de Defensa', 'Un Instituto armado de naturaleza militar', 'Un Instituto armado de naturaleza civil', 'Un cuerpo de policía autonómica', 'B', 'Art. 9.b LO 2/1986.'),
  (289, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 1', 'En el cumplimiento de las misiones de carácter militar que se le encomienden, la Guardia Civil depende de:', 'El Presidente del Gobierno directamente', 'El Ministro de Defensa', 'El Jefe del Estado Mayor de la Defensa', 'El Ministro del Interior', 'B', 'Art. 9.b LO 2/1986. En el desempeño de las funciones policiales depende del Ministro del Interior.'),
  (290, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 1', 'En tiempo de guerra y durante el estado de sitio, la Guardia Civil dependerá:', 'Conjuntamente de Interior y Defensa', 'Exclusivamente del Ministro del Interior', 'Exclusivamente del Ministro de Defensa', 'Del Jefe del Estado Mayor del Ejército de Tierra', 'C', 'Art. 9.b LO 2/1986.'),
  (291, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 1', '¿Cuál es el lema de la Guardia Civil que figura en sus acuartelamientos?', 'Todo por la Patria', 'Patria y Ley', 'Servir y Proteger', 'Honor y Gloria', 'A', 'Lema presente en las casas cuartel.'),
  (292, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 1', 'Según el artículo 1 de la Cartilla del Guardia Civil, la principal divisa del Guardia Civil ha de ser:', 'La disciplina', 'El valor', 'El honor', 'La lealtad', 'C', '«El honor ha de ser la principal divisa del Guardia Civil; debe por consiguiente conservarlo sin mancha».'),
  (293, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 1', '¿Quién es la patrona de la Guardia Civil?', 'Santa Bárbara', 'La Inmaculada Concepción', 'La Virgen del Carmen', 'La Virgen del Pilar', 'D', 'Se celebra el 12 de octubre.'),
  (294, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 1', '¿Qué ley regula los derechos y deberes de los miembros de la Guardia Civil?', 'La Ley Orgánica 12/2007, de 22 de octubre', 'La Ley Orgánica 11/2007, de 22 de octubre', 'La Ley 29/2014, de 28 de noviembre', 'La Ley Orgánica 9/2015, de 28 de julio', 'B', 'La LO 12/2007 regula el régimen disciplinario y la Ley 29/2014 el régimen de personal.'),
  (295, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 1', '¿Qué norma regula el régimen disciplinario de la Guardia Civil?', 'La Ley Orgánica 11/2007, de 22 de octubre', 'La Ley Orgánica 12/2007, de 22 de octubre', 'El Real Decreto Legislativo 5/2015', 'La Ley Orgánica 8/2014, de régimen disciplinario de las Fuerzas Armadas', 'B', 'LO 12/2007.'),
  (296, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 2', '¿Qué ley regula el régimen del personal de la Guardia Civil?', 'La Ley Orgánica 2/1986, de 13 de marzo', 'La Ley Orgánica 9/2015, de 28 de julio', 'La Ley 29/2014, de 28 de noviembre', 'La Ley 39/2007, de la carrera militar', 'C', 'La Ley 39/2007 es de la carrera militar de las Fuerzas Armadas y la LO 9/2015 del personal de la Policía Nacional.'),
  (297, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 2', '¿Cuál de las siguientes es una escala de la Guardia Civil?', 'La Escala de Cabos y Guardias', 'La Escala de Subinspección', 'La Escala Ejecutiva', 'La Escala Básica', 'A', 'Ley 29/2014: oficiales generales, oficiales, suboficiales y cabos y guardias. Las demás son escalas de la Policía Nacional.'),
  (298, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 2', '¿Qué empleos integran la Escala de Cabos y Guardias?', 'Guardia, Guardia Primero y Cabo', 'Guardia Civil, Cabo, Cabo Primero y Cabo Mayor', 'Guardia Civil, Cabo y Sargento', 'Cabo, Cabo Primero y Brigada', 'B', 'Ley 29/2014.'),
  (299, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 2', '¿Cuál de estas funciones corresponde en exclusiva a la Guardia Civil?', 'La expedición del pasaporte', 'El control de las entidades de seguridad privada', 'El control de armas y explosivos', 'La vigilancia del cumplimiento de la normativa sobre juego', 'C', 'Art. 12.1.B LO 2/1986. Las demás corresponden a la Policía Nacional.'),
  (300, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 2', 'La custodia de costas, fronteras, puertos y aeropuertos corresponde a:', 'La Policía Nacional', 'Salvamento Marítimo', 'La Guardia Civil', 'Las Fuerzas Armadas', 'C', 'Art. 12.1.B LO 2/1986.'),
  (301, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 2', '¿Qué unidad de la Guardia Civil se dedica a la protección de la naturaleza y el medio ambiente?', 'El GAR', 'El SEPRONA', 'La Agrupación de Tráfico', 'La UCO', 'B', 'Servicio de Protección de la Naturaleza, creado en 1988.'),
  (302, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 2', 'La vigilancia del tráfico en las vías públicas interurbanas corresponde a:', 'La Policía Nacional', 'La Dirección General de Tráfico con sus propios agentes', 'La Agrupación de Tráfico de la Guardia Civil', 'Las Policías Locales', 'C', 'Art. 12.1.B LO 2/1986.'),
  (303, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 2', 'La Unidad Central Operativa (UCO) de la Guardia Civil realiza funciones de:', 'Protección de la naturaleza', 'Vigilancia del tráfico', 'Escolta de altas personalidades', 'Policía judicial frente a la delincuencia grave y organizada', 'D', 'Depende de la Jefatura de Policía Judicial.'),
  (304, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 2', 'Los miembros de la Guardia Civil:', 'No pueden asociarse en ningún caso', 'Pueden afiliarse a sindicatos y hacer huelga', 'Pueden crear y afiliarse a asociaciones profesionales, pero no a sindicatos', 'Pueden afiliarse a partidos políticos', 'C', 'LO 11/2007.'),
  (305, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Guardia Civil · T4 · Test 2', '¿Qué órgano colegiado canaliza la participación de los miembros de la Guardia Civil a través de sus asociaciones profesionales?', 'El Consejo de la Guardia Civil', 'El Consejo de Política de Seguridad', 'La Junta de Seguridad', 'El Consejo de Estado', 'A', 'LO 11/2007.'),
