  (307, 'Guardia Civil – Cabos y Guardias', 'Tema 4. La Guardia Civil: naturaleza, funciones y régimen', 'Simulacro general · Guardia Civil', '¿Cuáles de estas funciones corresponden en exclusiva a la Guardia Civil? (varias correctas)', 'La conducción interurbana de presos y detenidos', 'El control de entrada y salida del territorio nacional', 'El resguardo fiscal del Estado', 'La expedición del DNI', 'AC', 'Art. 12.1.B LO 2/1986. El DNI y el control de entrada y salida corresponden a la Policía Nacional.'),
  (308, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Guardia Civil · T5 · Test 1', '¿Qué norma aprueba el texto refundido de la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial?', 'La Ley 18/2021, de 20 de diciembre', 'El Real Decreto 1428/2003, de 21 de noviembre', 'El Real Decreto Legislativo 6/2015, de 30 de octubre', 'El Real Decreto 818/2009, de 8 de mayo', 'C', 'El RD 1428/2003 es el Reglamento General de Circulación y el RD 818/2009 el Reglamento General de Conductores.'),
  (309, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Guardia Civil · T5 · Test 1', 'La tasa máxima de alcohol para conductores en general es de:', '0,8 g/l en sangre o 0,40 mg/l en aire espirado', '0,5 g/l en sangre o 0,25 mg/l en aire espirado', '0,25 g/l en sangre o 0,5 mg/l en aire espirado', '0,3 g/l en sangre o 0,15 mg/l en aire espirado', 'B', 'Art. 20 del Reglamento General de Circulación.'),
  (310, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Guardia Civil · T5 · Test 1', 'Para conductores noveles y profesionales, la tasa máxima de alcohol es de:', '0,0 g/l en todo caso', '0,2 g/l en sangre o 0,1 mg/l en aire espirado', '0,5 g/l en sangre o 0,25 mg/l en aire espirado', '0,3 g/l en sangre o 0,15 mg/l en aire espirado', 'D', 'Art. 20 del Reglamento General de Circulación.'),
  (311, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Guardia Civil · T5 · Test 1', 'Comete delito quien conduzca con una tasa de alcohol en aire espirado superior a:', '0,25 mg/l', '0,60 mg/l', '0,50 mg/l', '1,20 mg/l', 'B', 'Art. 379.2 CP: o con una tasa de alcohol en sangre superior a 1,2 g/l.'),
  (312, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Guardia Civil · T5 · Test 1', 'Comete delito quien conduzca a velocidad superior en vía interurbana en:', '80 km/h a la permitida', '100 km/h a la permitida', '50 km/h a la permitida', '60 km/h a la permitida', 'A', 'Art. 379.1 CP: 60 km/h en vía urbana u 80 km/h en vía interurbana.'),
  (313, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Guardia Civil · T5 · Test 1', '¿Con cuántos puntos comienza un conductor novel?', 'Ocho', 'Diez', 'Seis', 'Doce', 'A', 'Alcanza los 12 puntos si no pierde ninguno durante los dos primeros años.'),
  (314, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Guardia Civil · T5 · Test 1', '¿Cuál es el saldo máximo de puntos que puede alcanzar un conductor?', 'Doce', 'Catorce', 'Veinte', 'Quince', 'D', '12 iniciales + 2 tras tres años sin infracciones + 1 tras otros tres años.'),
  (315, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Guardia Civil · T5 · Test 1', 'La velocidad máxima de un turismo en autopistas y autovías es de:', '110 km/h', '130 km/h', '100 km/h', '120 km/h', 'D', 'Reglamento General de Circulación.'),
  (316, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Guardia Civil · T5 · Test 1', 'En vías urbanas de un único carril por sentido de circulación, la velocidad máxima genérica es de:', '30 km/h', '20 km/h', '40 km/h', '50 km/h', 'A', 'Desde el 11 de mayo de 2021. En vías de plataforma única es de 20 km/h y con dos o más carriles por sentido, 50 km/h.'),
