  (320, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Guardia Civil · T5 · Test 2', 'Al adelantar a ciclistas en vías interurbanas, la separación lateral mínima es de:', '2 metros', '1 metro', '0,5 metros', '1,5 metros', 'D', 'En vías con más de un carril por sentido es obligatorio cambiar completamente de carril.'),
  (321, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Guardia Civil · T5 · Test 2', 'Los menores de estatura igual o inferior a 135 cm deben viajar, con carácter general:', 'En cualquier asiento sin sistema específico', 'En el asiento delantero con cinturón', 'En los asientos traseros, con un sistema de retención infantil homologado', 'En los asientos traseros sin necesidad de sistema de retención', 'C', 'Reglamento General de Circulación, con las excepciones que prevé.'),
  (322, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Guardia Civil · T5 · Test 2', 'Según su gravedad, las infracciones de tráfico se clasifican en:', 'Leves, graves y muy graves', 'Faltas y delitos', 'Leves y graves', 'Graves y muy graves', 'A', 'Art. 74 del texto refundido de la Ley sobre Tráfico.'),
  (323, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Guardia Civil · T5 · Test 2', 'Las infracciones graves se sancionan con multa de:', '200 euros', '300 euros', '100 euros', '500 euros', 'A', 'Art. 80 LTSV: leves hasta 100 €, graves 200 € y muy graves 500 €, salvo excepciones.'),
  (324, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Guardia Civil · T5 · Test 2', 'El pago voluntario de una multa de tráfico dentro de los veinte días naturales siguientes a la notificación supone:', 'Una reducción del 50 % del importe', 'La anulación de la pérdida de puntos', 'Una reducción del 25 %', 'Una reducción del 30 %', 'A', 'Art. 94 LTSV (procedimiento sancionador abreviado).'),
  (325, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Guardia Civil · T5 · Test 2', 'Las infracciones leves de tráfico prescriben a los:', 'Seis meses', 'Un mes', 'Tres meses', 'Un año', 'C', 'Art. 112 LTSV: las graves y muy graves a los seis meses.'),
  (326, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Guardia Civil · T5 · Test 2', 'La edad mínima para obtener el permiso de conducción de la clase B es de:', 'Diecisiete años', 'Dieciséis años', 'Veintiún años', 'Dieciocho años', 'D', 'El permiso AM puede obtenerse a los quince años.'),
  (327, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Guardia Civil · T5 · Test 2', 'La profundidad mínima del dibujo de los neumáticos de un turismo es de:', '1,6 mm', '1 mm', '3 mm', '2 mm', 'A', 'En las ranuras principales de la banda de rodadura.'),
  (328, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Simulacro general · Guardia Civil', 'En una intersección sin señalizar, con carácter general, se debe ceder el paso a:', 'Los vehículos que se aproximen por la derecha', 'El vehículo que circule más rápido', 'El vehículo de mayor tamaño', 'Los vehículos que se aproximen por la izquierda', 'A', 'Art. 57 del Reglamento General de Circulación.'),
  (329, 'Guardia Civil – Cabos y Guardias', 'Tema 5. Seguridad vial', 'Simulacro general · Guardia Civil', '¿Cuáles de las siguientes conductas son delito contra la seguridad vial según el art. 379 CP? (varias correctas)', 'Circular a 140 km/h en una autovía limitada a 120 km/h', 'Conducir con una tasa de alcohol en aire espirado de 0,30 mg/l', 'Conducir con una tasa de alcohol en aire espirado de 0,70 mg/l', 'Circular a 140 km/h en una vía urbana limitada a 50 km/h', 'CD', 'Delito: más de 0,60 mg/l en aire o exceso de 60 km/h en vía urbana u 80 km/h en interurbana. Los otros dos casos son infracciones administrativas.')
) AS v(ord, curso, tema, test, enunciado, a, b, c, d, correcta, explicacion)
JOIN cursos c ON c.nombre = v.curso JOIN temas t ON t.curso_id = c.id AND t.nombre = v.tema
JOIN test_plantillas tp ON tp.numero_test = v.test ORDER BY v.ord;

-- Nº real de preguntas de cada test
UPDATE test_plantillas tp SET total_preguntas = x.n FROM (
  SELECT test_plantilla_id, count(*) AS n FROM preguntas GROUP BY test_plantilla_id) x
WHERE x.test_plantilla_id = tp.id AND tp.numero_test IN (SELECT test FROM (VALUES ('Aux. Administrativo · T1 · Test 1'), ('Aux. Administrativo · T1 · Test 2'), ('Aux. Administrativo · T2 · Test 1'), ('Aux. Administrativo · T2 · Test 2'), ('Aux. Administrativo · T3 · Test 1'), ('Aux. Administrativo · T3 · Test 2'), ('Aux. Administrativo · T4 · Test 1'), ('Aux. Administrativo · T4 · Test 2'), ('Aux. Administrativo · T5 · Test 1'), ('Aux. Administrativo · T5 · Test 2'), ('Simulacro general · Aux. Administrativo'), ('Policía Nacional · T1 · Test 1'), ('Policía Nacional · T1 · Test 2'), ('Policía Nacional · T2 · Test 1'), ('Policía Nacional · T2 · Test 2'), ('Policía Nacional · T3 · Test 1'), ('Policía Nacional · T3 · Test 2'), ('Policía Nacional · T4 · Test 1'), ('Policía Nacional · T4 · Test 2'), ('Policía Nacional · T5 · Test 1'), ('Policía Nacional · T5 · Test 2'), ('Simulacro general · Policía Nacional'), ('Guardia Civil · T1 · Test 1'), ('Guardia Civil · T1 · Test 2'), ('Guardia Civil · T2 · Test 1'), ('Guardia Civil · T2 · Test 2'), ('Guardia Civil · T3 · Test 1'), ('Guardia Civil · T3 · Test 2'), ('Guardia Civil · T4 · Test 1'), ('Guardia Civil · T4 · Test 2'), ('Guardia Civil · T5 · Test 1'), ('Guardia Civil · T5 · Test 2'), ('Simulacro general · Guardia Civil')) s(test));

