CREATE TEMP TABLE demo_resp ON COMMIT DROP AS
SELECT di.k, u.id AS alumno_id, tp.id AS test_id, di.modo, di.dias, p.id AS pregunta_id,
       abs(('x' || substr(md5(di.email || '|' || di.k || '|' || p.enunciado), 1, 8))::bit(32)::int) % 100 < di.nivel AS ok
FROM demo_intentos di
JOIN usuarios u ON u.email = di.email
JOIN test_plantillas tp ON tp.numero_test = di.test
JOIN preguntas p ON p.test_plantilla_id = tp.id;

INSERT INTO test_intentos (alumno_id, test_plantilla_id, fecha_intento, fallos_ultimo, total_preguntas, modo, personalizado)
SELECT alumno_id, test_id,
       (now() AT TIME ZONE 'UTC') - make_interval(days => min(dias), hours => (min(k) % 9) + 1),
       count(*) FILTER (WHERE NOT ok), count(*), min(modo), false
FROM demo_resp GROUP BY k, alumno_id, test_id;

-- Un test personalizado de la alumna demo (para la gráfica de evolución)
INSERT INTO test_intentos (alumno_id, test_plantilla_id, fecha_intento, fallos_ultimo, total_preguntas, modo, personalizado)
SELECT id, NULL, (now() AT TIME ZONE 'UTC') - interval '2 days 3 hours', 3, 20, 'examen', true
FROM usuarios WHERE email = 'alumna.demo@academiamega.net';

INSERT INTO respuestas_alumnos (alumno_id, pregunta_id, es_correcta)
SELECT alumno_id, pregunta_id, ok FROM demo_resp;

-- Mazo de repaso: preguntas falladas en el último intento de cada test
INSERT INTO registro_fallos (alumno_id, pregunta_id, repasada)
SELECT DISTINCT r.alumno_id, r.pregunta_id, false FROM demo_resp r
WHERE NOT r.ok AND r.k = (SELECT max(k) FROM demo_resp r2 WHERE r2.alumno_id = r.alumno_id AND r2.test_id = r.test_id);

-- Ranking: puntos = aciertos acumulados
INSERT INTO puntuaciones (usuario_id, alumno_nombre, puntos, fecha)
SELECT u.id, u.nombre, count(*) FILTER (WHERE r.ok), to_char(now(), 'YYYY-MM-DD')
FROM demo_resp r JOIN usuarios u ON u.id = r.alumno_id GROUP BY u.id, u.nombre;

COMMIT;
